function invoiceBalanceSafe(invoice){
  if(!invoice)return 0;
  const total=typeof invoiceTotal==='function'?Number(invoiceTotal(invoice)||0):Number(invoice.total||0);
  const payments=(state?.adminLifecycleV56?.payments||[]).filter(row=>row.invoiceId===invoice.id&&!row.reversedAt).reduce((sum,row)=>sum+Number(row.amount||0),0);
  const credits=(state?.invoices||[]).filter(row=>row.creditedInvoiceId===invoice.id&&String(row.status||'').toLowerCase()!=='voided').reduce((sum,row)=>sum+(typeof invoiceTotal==='function'?Number(invoiceTotal(row)||0):0),0);
  return Math.max(0,round2(total-payments-credits));
}

function localDateISO(date=new Date()){
  const y=date.getFullYear(), m=String(date.getMonth()+1).padStart(2,'0'), d=String(date.getDate()).padStart(2,'0');
  return `${y}-${m}-${d}`;
}
function currentMonth(){ return localDateISO().slice(0,7); }
function monthLabel(month){ const [y,m]=month.split('-').map(Number); return `${MONTH_NAMES[m-1]} ${y}`; }
function fmtDate(iso){ if(!iso) return '—'; return new Date(`${iso}T12:00:00`).toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'}); }
function fmtShortDate(iso){ if(!iso) return '—'; return new Date(`${iso}T12:00:00`).toLocaleDateString('en-ZA',{day:'numeric',month:'short'}); }
function dateAdd(iso, days){ const d=new Date(`${iso}T12:00:00`); d.setDate(d.getDate()+days); return localDateISO(d); }
