function startOfWeek(iso=localDateISO()){
  const d=new Date(`${iso}T12:00:00`); let day=d.getDay(); if(day===0) day=7; d.setDate(d.getDate()-(day-1)); return localDateISO(d);
}
function weekDates(weekStart){ return DAYS.map((_,i)=>dateAdd(weekStart,i)); }
function dayName(iso){ return DAYS[new Date(`${iso}T12:00:00`).getDay()-1] || 'Sunday'; }
function isMonth(date, month){ return String(date||'').slice(0,7)===month; }
function lineTotal(line){ return round2((Number(line.qty)||0)*(Number(line.unitPrice)||0)); }
function invoiceSubtotal(inv){ return round2((inv.lineItems||[]).reduce((s,l)=>s+lineTotal(l),0)); }
function activeVatRate(){ return state?.business?.vatRegistered==='yes' ? Number(state.business.vatRate ?? 15) : 0; }
function invoiceVatRate(inv){ return Number.isFinite(Number(inv?.vatRate)) ? Number(inv.vatRate) : activeVatRate(); }
function invoiceVat(inv){ return round2(invoiceSubtotal(inv) * invoiceVatRate(inv) / 100); }
function invoiceTotal(inv){ return round2(invoiceSubtotal(inv) + invoiceVat(inv)); }
function statusClass(status=''){ const s=status.toLowerCase(); if(s.includes('paid')) return 'paid'; if(s.includes('sent')) return 'sent'; if(s.includes('credit')) return 'credited'; if(s.includes('ready')) return 'ready'; if(s.includes('draft')||s.includes('review')||s.includes('unpaid')) return 'review'; return 'neutral'; }
