/* ---------- Shared monthly invoice preparation ---------- */
function visitsFor(clientId, month){ return state.visits.filter(v=>v.clientId===clientId&&isMonth(v.date,month)&&!['Access failed','Weather delay','Unable to complete'].includes(v.outcome)); }
function approvedQuotesFor(clientId, month){
  return state.quotes.filter(quote=>quote.clientId===clientId&&quote.status==='Approved'&&(state.visits||[]).some(visit=>{
    if(visit.clientId!==clientId||!isMonth(visit.date,month))return false;
    const job=(state.schedules||[]).find(item=>item.id===visit.scheduledJobId);
    return job?.quoteId===quote.id;
  }));
}
function invoicesForClientMonth(clientId,month){return state.invoices.filter(i=>i.clientId===clientId&&i.month===month&&i.status!=='Credited');}
function invoiceForClientMonth(clientId, month){
  const rows=invoicesForClientMonth(clientId,month);
  return rows.find(inv=>invoiceDeliveryStatus(inv)!=='Sent'&&['Draft','Ready'].includes(inv.status))||rows.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))[0];
}
function billingJobForVisitV59380(visit){
  return (state.schedules||[]).find(item=>String(item.id||'')===String(visit?.scheduledJobId||''))||null;
}
function billingIsOnceOffVisitV59380(visit,job=billingJobForVisitV59380(visit)){
  const marker=String(job?.workMarker||job?.marker||'').trim().toUpperCase();
  const text=String(`${job?.workKind||''} ${job?.revenueType||''} ${job?.queueSource||''} ${job?.reason||''} ${visit?.workKind||''} ${visit?.revenueType||''}`).toLowerCase().replace(/[^a-z0-9]+/g,' ');
  return marker==='O'||/once off|one off|ad hoc|additional work|direct project/.test(text);
}
function billingSourceLines(client,month){
  const visits=visitsFor(client.id,month),lines=[],quoted=new Set(),recurring=[];
  visits.forEach(visit=>{
    if(visit.outcome==='Partially completed'){
      lines.push({id:uid('line'),sourceKey:`partial-work:${visit.id}`,sourceType:'partial-work-review',sourceManaged:true,description:`Partially completed work — ${String((visit.workDone||[]).join(', ')||visit.outcomeNote||'office review required')}`,qty:1,unitPrice:0,extra:true,approved:false,sourceVisitId:visit.id});
      if(String(visit.extraDescription||'').trim())lines.push({id:uid('line'),sourceKey:`visit-extra:${visit.id}`,sourceType:'visit-extra',sourceManaged:true,description:visit.extraDescription,qty:1,unitPrice:0,extra:true,approved:false,sourceVisitId:visit.id});
      return;
    }
    const job=billingJobForVisitV59380(visit),quote=job?.quoteId?(state.quotes||[]).find(item=>item.id===job.quoteId):null,onceOff=billingIsOnceOffVisitV59380(visit,job);
    if(quote?.status==='Approved'&&!quoted.has(quote.id)){
      quoted.add(quote.id);
      (quote.lineItems||[]).forEach((line,index)=>lines.push({id:uid('line'),sourceKey:`quote:${quote.id}:${line.id||index}`,sourceType:'completed-quote',sourceManaged:true,description:line.description,qty:Number(line.qty)||1,unitPrice:Number(line.unitPrice)||0,extra:true,approved:Number(line.unitPrice)>0,sourceQuoteId:quote.id,sourceVisitId:visit.id}));
    }else if(job?.quoteId&&!quoted.has(job.quoteId)){
      quoted.add(job.quoteId);
      lines.push({id:uid('line'),sourceKey:`completed-quote:${job.quoteId}:${visit.id}`,sourceType:'completed-quote-review',sourceManaged:true,description:`Completed quoted work — ${String((visit.workDone||[]).join(', ')||'review required')}`,qty:1,unitPrice:0,extra:true,approved:false,sourceQuoteId:job.quoteId,sourceVisitId:visit.id});
    }else if(onceOff){
      /* v59.3.80: once-off completions use a dedicated immediate invoice. */
    }else if((job?jobRevenueTypeV9(job):visit.revenueType||'Recurring contract')==='Recurring contract')recurring.push(visit);
    else if(!String(visit.extraDescription||'').trim())lines.push({id:uid('line'),sourceKey:`completed-work:${visit.id}`,sourceType:'completed-additional-work',sourceManaged:true,description:String((visit.workDone||[]).join(', ')||'Completed additional work'),qty:1,unitPrice:0,extra:true,approved:false,sourceVisitId:visit.id});
    if(String(visit.extraDescription||'').trim())lines.push({id:uid('line'),sourceKey:`visit-extra:${visit.id}`,sourceType:'visit-extra',sourceManaged:true,description:visit.extraDescription,qty:1,unitPrice:0,extra:true,approved:false,sourceVisitId:visit.id});
  });
  if(recurring.length&&Number(client.monthlyFee)>0)lines.unshift({id:uid('line'),sourceKey:`contract:${client.id}:${month}`,sourceType:'recurring-contract',sourceManaged:true,description:`Garden service — ${monthLabel(month)} (${recurring.length} visit${recurring.length===1?'':'s'})`,qty:1,unitPrice:Number(client.monthlyFee),extra:false,approved:true});
  else if(recurring.length)lines.unshift({id:uid('line'),sourceKey:`visits:${client.id}:${month}`,sourceType:'completed-visits',sourceManaged:true,description:`Garden service — ${monthLabel(month)}`,qty:recurring.length,unitPrice:0,extra:false,approved:true});
  return lines;
}
function normaliseLegacyBillingSources(inv,client,month){
  (inv.lineItems||[]).forEach((line,index)=>{
    if(line.sourceKey)return;
    if(line.sourceVisitId)line.sourceKey=`visit-extra:${line.sourceVisitId}`;
    else if(line.sourceQuoteId)line.sourceKey=`quote:${line.sourceQuoteId}:${line.id||index}`;
    else if(index===0&&!line.extra)line.sourceKey=`contract:${client.id}:${month}`;
    if(line.sourceKey&&line.sourceManaged===undefined)line.sourceManaged=false;
  });
}
function isDedicatedQuoteBillingInvoiceV5896(inv){
  return !!(inv&&inv.sourceQuoteIdV5895&&inv.quoteBillingRoleV5895);
}
function repairDedicatedQuoteBillingInvoiceV5896(inv){
  if(!isDedicatedQuoteBillingInvoiceV5896(inv))return;
  (inv.lineItems||[]).forEach(line=>{
    if(line.sourceType==='quote-billing'||String(line.sourceKey||'').startsWith(`quote:${inv.sourceQuoteIdV5895}:`)){
      delete line.sourceUnavailable;
      if(line.extra===false)line.approved=true;
      if(inv.quoteBillingRoleV5895==='full-upfront'&&/^Accepted quote invoiced before completion/i.test(String(line.description||''))){
        line.description=String(line.description).replace(/^Accepted quote invoiced before completion/i,'Quoted work from accepted quote');
      }
    }
  });
  inv.total=invoiceTotal(inv);
}
function reconcileDraftBillingSources(inv,client,month,reservedKeys=new Set()){
  if(isDedicatedQuoteBillingInvoiceV5896(inv)){
    repairDedicatedQuoteBillingInvoiceV5896(inv);
    return;
  }
  normaliseLegacyBillingSources(inv,client,month);
  const ownKeys=new Set((inv.lineItems||[]).map(line=>line.sourceKey).filter(Boolean));
  const candidates=billingSourceLines(client,month).filter(line=>!reservedKeys.has(line.sourceKey)||ownKeys.has(line.sourceKey)),candidateMap=new Map(candidates.map(line=>[line.sourceKey,line])),existingMap=new Map();
  (inv.lineItems||[]).forEach(line=>{if(line.sourceKey&&!existingMap.has(line.sourceKey))existingMap.set(line.sourceKey,line);});
  candidates.forEach(candidate=>{
    const existing=existingMap.get(candidate.sourceKey);
    if(!existing){inv.lineItems.push(candidate);return;}
    delete existing.sourceUnavailable;
    if(existing.sourceManaged===true){
      const pricedExtra=existing.sourceType==='visit-extra'&&Number(existing.unitPrice)>0;
      existing.description=candidate.description;existing.qty=candidate.qty;existing.extra=candidate.extra;
      if(!pricedExtra)existing.unitPrice=candidate.unitPrice;
      if(existing.sourceType!=='visit-extra')existing.approved=candidate.approved;
    }
  });
  (inv.lineItems||[]).forEach(line=>{if(line.sourceKey&&!candidateMap.has(line.sourceKey)){line.sourceUnavailable=true;line.approved=false;}});
  inv.total=invoiceTotal(inv);
}
function buildDraftForClient(client,month,options={}){
  const lines=options.lines||billingSourceLines(client,month);if(!lines.length)return null;
  const sequence=Math.max(1,Number(options.sequence)||1),suffix=sequence>1?`:S${sequence}`:'';
  const inv={id:uid('inv'),billingBatchId:`TB-${month.replace('-','')}-${client.id}${suffix}`,supplementSequence:sequence,accountingSystem:'unconnected',externalInvoiceId:'',externalInvoiceNumber:'',syncStatus:'not-connected',number:'Draft',clientId:client.id,month,status:'Draft',deliveryStatus:'Not sent',paymentStatus:'Unpaid',vatRate:activeVatRate(),version:1,lineItems:lines,notes:sequence>1?`Supplemental billing review created for work received after an earlier invoice. ${state.business.invoiceNote||''}`:state.business.invoiceNote||'',history:sequence>1?[{date:new Date().toISOString(),action:'Supplemental billing review created for late work'}]:[],createdAt:new Date().toISOString()};
  inv.total=invoiceTotal(inv); return inv;
}
function ensureDrafts(month){
  if(state.closures[month]) return;
  state.clients.filter(c=>c.status==='active').forEach(c=>{
    const allInvoices=invoicesForClientMonth(c.id,month);
    const quoteBillingInvoices=allInvoices.filter(isDedicatedQuoteBillingInvoiceV5896);
    quoteBillingInvoices.forEach(repairDedicatedQuoteBillingInvoiceV5896);
    const invoices=allInvoices.filter(inv=>!isDedicatedQuoteBillingInvoiceV5896(inv));
    const open=invoices.filter(inv=>invoiceDeliveryStatus(inv)!=='Sent'&&['Draft','Ready'].includes(inv.status));
    invoices.forEach(inv=>normaliseLegacyBillingSources(inv,c,month));
    if(!invoices.length){
      const draft=buildDraftForClient(c,month); if(draft) state.invoices.push(draft);
      return;
    }
    const usedByClosed=new Set(invoices.filter(inv=>!open.includes(inv)).flatMap(inv=>(inv.lineItems||[]).map(line=>line.sourceKey).filter(Boolean)));
    if(open.length){
      const target=open[0],usedByOtherOpen=new Set(open.slice(1).flatMap(inv=>(inv.lineItems||[]).map(line=>line.sourceKey).filter(Boolean)));
      reconcileDraftBillingSources(target,c,month,new Set([...usedByClosed,...usedByOtherOpen]));
      return;
    }
    const used=new Set(invoices.flatMap(inv=>(inv.lineItems||[]).map(line=>line.sourceKey).filter(Boolean))),late=billingSourceLines(c,month).filter(line=>!used.has(line.sourceKey));
    if(late.length){const existing=invoices.slice().sort((a,b)=>activeInvoicePriorityV5604?.(b)-activeInvoicePriorityV5604?.(a))[0]||invoices[0];if(existing){existing.lateWorkPendingV5604=late.map(line=>line.sourceKey||line.description);existing.needsOfficeReview=true;existing.reviewReason='Additional completed work was received after this month already had an invoice. Review the existing invoice or carry the work forward.';}}
  });
  save();
}

function invoiceNeedsReview(inv){
  const keys=new Set(),duplicates=new Set();
  (inv.lineItems||[]).forEach(line=>{if(line.sourceKey){if(keys.has(line.sourceKey))duplicates.add(line.sourceKey);keys.add(line.sourceKey);}});
  return duplicates.size>0||(inv.lineItems||[]).some(l=>l.sourceUnavailable||!String(l.description||'').trim()||!Number.isFinite(Number(l.qty))||Number(l.qty)<=0||!Number.isFinite(Number(l.unitPrice))||Number(l.unitPrice)<=0||(l.extra&&(!l.approved||Number(l.unitPrice)<=0)));
}
function assignInvoiceNumber(inv){
  if(inv.number && inv.number!=='Draft') return;
  const issueDate=String(inv.issueDate||localDateISO()).slice(0,10);
  const year=/^\d{4}-\d{2}-\d{2}$/.test(issueDate)?Number(issueDate.slice(0,4)):new Date().getFullYear();
  const prefix=String(state.business.invoicePrefix||'INV').trim().toUpperCase().replace(/[^A-Z0-9]+/g,'')||'INV';
  if(Number(state.business.invoiceSequenceYear)!==year){state.business.invoiceSequenceYear=year;state.business.nextInvoice=1;}
  let next=Math.max(1,Number(state.business.nextInvoice||1)),number='';
  const credit=inv.status==='Credited'||inv.transactionType==='Credit Note';
  const used=new Set((state.invoices||[]).filter(row=>row.id!==inv.id).map(row=>String(row.number||'').trim()));
  do{number=`${prefix}${credit?'-CN':''}-${year}-${String(next).padStart(4,'0')}`;next+=1;}while(used.has(number));
  inv.number=number;inv.issueDate=issueDate;state.business.nextInvoice=next;state.business.invoiceSequenceYear=year;
}

