  $('clientList').innerHTML=clients.map(c=>`<article class="client-row" onclick="editClient('${c.id}')"><div><strong>${esc(c.name)}</strong><small>${esc(c.address)} • ${esc(c.suburb)}<br>${esc(c.contact||'No contact')} • ${esc(c.frequency)}</small></div><div class="client-row-meta"><span class="status-badge ${c.incomplete?'review':c.status==='active'?'ready':'neutral'}">${c.incomplete?'Incomplete':esc(c.status)}</span><strong>${money(c.monthlyFee)}</strong></div></article>`).join('')||'<p>No clients match this filter.</p>';
