  const combined=[...Object.entries(bySuburb).map(([k,v])=>[`Suburb: ${k}`,v]),...Object.entries(byTeam).map(([k,v])=>[`Team: ${k}`,v]),...Object.entries(byDay).map(([k,v])=>[`Day: ${k}`,v])].sort((a,b)=>b[1]-a[1]).slice(0,10);const max=Math.max(1,...combined.map(x=>x[1]));
