function compressOpportunityPhoto(file){
  return new Promise((resolve,reject)=>{if(!file||!String(file.type).startsWith('image/')){reject(new Error('Please take a photo.'));return;}const reader=new FileReader();reader.onerror=()=>reject(new Error('The photo could not be read.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('The photo could not be opened.'));img.onload=()=>{let w=img.naturalWidth||img.width,h=img.naturalHeight||img.height;const scale=Math.min(1,1200/Math.max(w,h));w=Math.max(1,Math.round(w*scale));h=Math.max(1,Math.round(h*scale));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,w,h);resolve(canvas.toDataURL('image/jpeg',.74));};img.src=String(reader.result);};reader.readAsDataURL(file);});
}
