/* ---------- MVP completion enhancements ---------- */
function clientCompletionIssues(client){
  const issues=[];
  if(!String(client?.name||'').trim()) issues.push('client name');
  if(!String(client?.address||'').trim()) issues.push('property address');
  if(!String(client?.suburb||'').trim()) issues.push('suburb');
  if(!String(client?.whatsapp||'').trim() && !String(client?.email||'').trim()) issues.push('WhatsApp or email');
  if(client?.incomplete && !issues.length) issues.push('admin confirmation');
  return issues;
}
function invoiceClientIssues(inv){ return clientCompletionIssues(clientById(inv?.clientId)||{}); }
function invoiceNeedsReview(inv){
  const keys=new Set(),duplicates=new Set();
  (inv.lineItems||[]).forEach(line=>{if(line.sourceKey){if(keys.has(line.sourceKey))duplicates.add(line.sourceKey);keys.add(line.sourceKey);}});
  return invoiceClientIssues(inv).length>0||duplicates.size>0||(inv.lineItems||[]).some(l=>l.sourceUnavailable||!String(l.description||'').trim()||!Number.isFinite(Number(l.qty))||Number(l.qty)<=0||!Number.isFinite(Number(l.unitPrice))||Number(l.unitPrice)<=0||(l.extra&&(!l.approved||Number(l.unitPrice)<=0)));
}
