function parseDelimited(text,delimiter=','){
  const rows=[];let row=[],cell='',quoted=false;
  for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===delimiter&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);cell='';if(row.some(v=>String(v).trim()))rows.push(row);row=[];}else cell+=ch;}
  row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);return rows;
}
function normaliseHeader(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
function findColumn(headers,words){return headers.findIndex(h=>words.some(w=>h===w||h.includes(w)));}
function readClientSpreadsheet(event){
  const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{
    const text=String(reader.result||'');const delimiter=(text.split('\n')[0].match(/\t/g)||[]).length>(text.split('\n')[0].match(/,/g)||[]).length?'\t':',';const rows=parseDelimited(text,delimiter);if(rows.length<2){toast('No client rows were found in this file.','error');return;}
    const headers=rows[0].map(normaliseHeader);const col={name:findColumn(headers,['client name','customer name','client','customer','name']),address:findColumn(headers,['property address','service address','address','street']),suburb:findColumn(headers,['suburb','area','town']),whatsapp:findColumn(headers,['whatsapp','mobile','phone','cell']),email:findColumn(headers,['email','e mail']),monthlyFee:findColumn(headers,['monthly fee','fee','price','amount']),frequency:findColumn(headers,['frequency','service frequency']),preferredDay:findColumn(headers,['preferred day','day'])};
    spreadsheetRows=rows.slice(1).map((r,i)=>({selected:true,name:col.name>=0?r[col.name]||'':'',address:col.address>=0?r[col.address]||'':'',suburb:col.suburb>=0?r[col.suburb]||'':'',whatsapp:col.whatsapp>=0?r[col.whatsapp]||'':'',email:col.email>=0?r[col.email]||'':'',monthlyFee:col.monthlyFee>=0?Number(String(r[col.monthlyFee]||'').replace(/[^0-9.-]/g,''))||0:0,frequency:col.frequency>=0?r[col.frequency]||'Custom':'Custom',preferredDay:col.preferredDay>=0?r[col.preferredDay]||'Friday':'Friday',sourceRow:i+2})).filter(r=>r.name||r.address||r.whatsapp||r.email);
    renderSpreadsheetRows();$('spreadsheetImportMeta').textContent=`${spreadsheetRows.length} row${spreadsheetRows.length===1?'':'s'} detected. Review before importing.`;
  };reader.readAsText(file);
}
