  $('yearSummaryCards').innerHTML=[['Invoiced',money(totalInvoiced),'Across 12 months',''],['Paid',money(paid),`${money(unpaid)} unpaid`,'good'],['Unpaid',money(unpaid),'Outstanding across period',unpaid?'alert':''],['Credits',money(credits),'Credit notes issued',''],['Visits',visits,'Completed work records',''],['Average / month',money(avg),'Average invoiced revenue','']].map(metricCardHtml).join('');
  const max=Math.max(1,...data.map(m=>m.invoiced));$('yearOverviewChart').innerHTML=data.map(m=>`<div class="year-month-column"><div class="year-bars"><i class="year-bar invoiced" style="height:${Math.max(3,m.invoiced/max*100)}%" title="Invoiced ${money(m.invoiced)}"></i><i class="year-bar paid" style="height:${Math.max(3,m.paid/max*100)}%" title="Paid ${money(m.paid)}"></i></div><strong>${monthLabel(m.month).slice(0,3)}</strong><small>${money(m.invoiced)}</small></div>`).join('');
  $('yearOverviewTable').innerHTML=data.map(m=>`<tr><td><strong>${monthLabel(m.month)}</strong></td><td>${money(m.invoiced)}</td><td>${money(m.paid)}</td><td>${money(m.unpaid)}</td><td>${money(m.credited)}</td><td>${m.visitsCount}</td><td>${m.activeClients}</td></tr>`).join('');
