function accountantExportPeriodV49(){
  if(activeView==='year' && typeof businessPeriodV23==='function'){
    const period=businessPeriodV23();
    return {start:period.start,end:period.end,label:period.label||`${period.start} to ${period.end}`};
  }
  const month=$('reportMonth')?.value||currentMonth();
  const end=typeof endOfMonthV23==='function'?endOfMonthV23(month):localDateISO(new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0));
  return {start:`${month}-01`,end,label:monthLabel(month)};
}
function accountantDocumentDateV49(invoice){
  return String(invoice.sentAt||invoice.createdAt||`${invoice.month||currentMonth()}-01`).slice(0,10);
}
function exportQuickBooksCsv(){
  const period=accountantExportPeriodV49();
  const rows=[['Transaction Date','Document Type','Document Number','Customer','Customer Reference','Description','Amount Excluding VAT','VAT Amount','Total Amount','Amount Paid','Outstanding Balance','Status']];
  const documents=(state.invoices||[]).filter(inv=>{
    if(['Draft','Ready'].includes(inv.status))return false;
    const date=accountantDocumentDateV49(inv);
    return date>=period.start&&date<=period.end;
  }).sort((a,b)=>accountantDocumentDateV49(a).localeCompare(accountantDocumentDateV49(b)));
  documents.forEach(inv=>{
    const client=clientById(inv.clientId)||{};
    const isCredit=inv.status==='Credited'||inv.transactionType==='Credit Note';
    const sign=isCredit?-1:1;
    const total=round2(invoiceTotal(inv)*sign);
    const exVat=round2(invoiceSubtotal(inv)*sign);
    const vat=round2(invoiceVat(inv)*sign);
    const paidStatus=invoicePaymentStatus(inv)==='Paid';
    const amountPaid=!isCredit&&paidStatus?round2(invoiceTotal(inv)):0;
    const balance=isCredit?0:round2(Math.max(0,invoiceTotal(inv)-amountPaid));
    const descriptions=(inv.lineItems||[]).map(line=>String(line.description||'').trim()).filter(Boolean).join('; ')||inv.notes||'';
    const status=isCredit?`Credit note ${invoiceDeliveryStatus(inv)}`:`${invoiceDeliveryStatus(inv)} / ${invoicePaymentStatus(inv)}`;
    rows.push([
      accountantDocumentDateV49(inv),
      isCredit?'Credit note':'Invoice',
      inv.number||'',
      client.name||'',
      client.accountReference||client.customerReference||'',
      descriptions,
      exVat,
      vat,
      total,
      amountPaid,
      balance,
      status
    ]);
    if(!isCredit&&paidStatus){
      const paymentDate=String(inv.paidAt||inv.sentAt||inv.createdAt||accountantDocumentDateV49(inv)).slice(0,10);
      if(paymentDate>=period.start&&paymentDate<=period.end){
        rows.push([
          paymentDate,
          'Payment',
          `PAY-${inv.number||inv.id}`,
          client.name||'',
          client.accountReference||client.customerReference||'',
          `Payment received for ${inv.number||'invoice'}`,
          0,
          0,
          0,
          round2(invoiceTotal(inv)),
          0,
          'Received'
        ]);
      }
    }
  });
  downloadCsv(`tuinbooks-accountant-${period.start}-to-${period.end}.csv`,rows);
  toast(`Accountant CSV exported for ${period.label}.`);
}

function renderEmailConnectionStatus(){const mode=$('settingEmailMode').value;const email=$('settingSendingEmail').value||state.business.email||'';$('emailConnectionStatus').innerHTML=mode==='connected'?`<span class="status-badge review">Backend connection required</span><p>${esc(email||'Business email')} will be connected securely during the Supabase phase. The browser prototype cannot send directly.</p>`:`<span class="status-badge ready">Prototype mode</span><p>Invoice email buttons open the computer's default email app with the recipient, subject and invoice summary filled in.</p>`;}
async function openTestEmail(){
  const email=$('settingSendingEmail')?.value||state.business.email||'';
  if(!email){toast('Add and save the business email first.','error');return;}
  if(backendV28.mode!=='supabase'||!backendV28.client||!backendV28.user){toast('Sign in to TuinBooks before sending a test email.','error');return;}
  if(!backendIsAdminV30()){toast('Only an owner or administrator can test email delivery.','error');return;}
  const button=$('testEmailBtn'),original=button?.textContent||'Send test email';if(button){button.disabled=true;button.textContent='Sending…';}
  try{
    state.business.emailSenderName=$('settingEmailSenderName')?.value.trim()||state.business.name||'';
    state.business.sendingEmail=$('settingSendingEmail')?.value.trim()||state.business.email||'';
    state.business.replyTo=$('settingReplyTo')?.value.trim()||state.business.sendingEmail||state.business.email||'';
    state.business.emailMode='connected';save();
    if(!await syncCoreSnapshotV28(true))throw new Error('The business email settings could not be saved online.');
    const data=await invokeTuinBooksEmailV5609({action:'test-connection',requestId:crypto.randomUUID()});
    toast(`Test email sent to ${data.recipient||email}.`);
  }catch(error){toast(await emailFunctionErrorV5609(error),'error');}
  finally{if(button){button.disabled=false;button.textContent=original;}}
}
