function recurrenceAnchorV10(client,dates=[]){
  if(validDateIsoV53(client.recurrenceAnchorDate))return client.recurrenceAnchorDate;
  const existing=state.schedules.filter(j=>j.clientId===client.id).sort((a,b)=>a.date.localeCompare(b.date))[0];
  if(existing?.date){client.recurrenceAnchorDate=existing.date;return existing.date;}
  const created=validDateIsoV53(client.createdAt)?client.createdAt:localDateISO(),week=startOfWeek(created),idx=Math.max(0,DAYS.indexOf(client.preferredDay));
  client.recurrenceAnchorDate=dateAdd(week,idx);return client.recurrenceAnchorDate;
}
function monthlyDueDateV53(client,yearMonth,anchor){
  const [year,month]=yearMonth.split('-').map(Number),preferredIndex=Math.max(0,DAYS.indexOf(client.preferredDay)),jsDay=preferredIndex+1;
  const anchorOrdinal=Math.min(5,Math.ceil(Number(anchor.slice(8,10))/7));
  const first=new Date(year,month-1,1,12),offset=(jsDay-first.getDay()+7)%7;
  let day=1+offset+(anchorOrdinal-1)*7;
  const lastDay=new Date(year,month,0,12).getDate();while(day>lastDay)day-=7;
  return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
}
function clientDueInWeekV10(client,weekStart,dates,wasAlreadyInWeek=false){
  if(wasAlreadyInWeek)return true;
  const frequency=String(client.frequency||'Weekly').toLowerCase();
  if(frequency.includes('custom'))return false;
  if(frequency.includes('weekly')&&!frequency.includes('fortnight'))return true;
  const idx=Math.max(0,DAYS.indexOf(client.preferredDay)),target=dates[idx],anchor=recurrenceAnchorV10(client,dates);
  if(target<anchor)return false;
  if(frequency.includes('fortnight'))return Math.floor(daysBetweenV10(startOfWeek(anchor),weekStart)/7)%2===0;
  if(frequency.includes('month'))return target===monthlyDueDateV53(client,target.slice(0,7),anchor);
  return true;
}
function showGenerationResultV10(message){const el=$('scheduleGenerationResult');if(!el)return;el.innerHTML=message;el.classList.remove('hidden');}
function generateRecurringWeekV9(){
  const week=$('scheduleWeekPicker').value||startOfWeek(localDateISO()),dates=weekDates(week),dateSet=new Set(dates);
  const weekJobs=state.schedules.filter(j=>dateSet.has(j.date));
  const existingRecurringClientIds=new Set(weekJobs.filter(j=>jobRevenueTypeV9(j)==='Recurring contract').map(j=>j.clientId));
  const preserved=weekJobs.filter(j=>j.status==='completed'||j.locked||jobRevenueTypeV9(j)!=='Recurring contract');
  const preservedRecurringIds=new Set(preserved.filter(j=>jobRevenueTypeV9(j)==='Recurring contract').map(j=>j.clientId));
  const removed=weekJobs.length-preserved.length;
  state.schedules=state.schedules.filter(j=>!dateSet.has(j.date)).concat(preserved);
  let created=0,skipped=0;
  state.clients.filter(c=>c.status==='active').forEach(c=>{
    if(preservedRecurringIds.has(c.id))return;
    if(!clientDueInWeekV10(c,week,dates,existingRecurringClientIds.has(c.id))){skipped++;return;}
    const idx=DAYS.indexOf(c.preferredDay);if(idx<0){skipped++;return;}
    state.schedules.push({id:uid('sch'),date:dates[idx],clientId:c.id,teamId:'',clusterId:c.clusterId,status:'scheduled',estimatedHours:c.estimatedHours||1,sort:99,locked:false,revenueType:'Recurring contract',workTypeIds:[...(c.workTypeIds||[])],autoGenerated:true,manualOverride:false});created++;
  });
  autoAssignUnlockedJobsV9(dates);save();renderSchedule();
  const kept=preserved.length;
  showGenerationResultV10(`<strong>Smart week rebuilt.</strong> ${created} recurring visit${created===1?'':'s'} generated, ${kept} completed/locked/special job${kept===1?'':'s'} kept, and ${removed} unlocked recurring job${removed===1?'':'s'} replaced. Cluster and safe-capacity assignment has been recalculated.`);
  toast(`Smart week rebuilt: ${created} recurring visit${created===1?'':'s'} generated.`);
}
