/* ---------- v11 route-first smart scheduling ---------- */
function dayIndexV11(day){const index=DAYS.indexOf(day);return index<0?0:index;}
function dayDistanceV11(a,b){return Math.abs(Number(a)-Number(b));}
function averagePreferredDayV11(jobs){
  if(!jobs.length)return 0;
  return jobs.reduce((sum,job)=>sum+dayIndexV11(clientById(job.clientId)?.preferredDay),0)/jobs.length;
}
function slotClusterSetV11(slot){return slot.clusters instanceof Set?slot.clusters:new Set();}
function slotRoutingScoreV11(slot,clusterId,jobs,slots){
  const safe=safeCapacityV9(slot.team),hours=jobs.reduce((sum,job)=>sum+Number(job.estimatedHours||0),0),projected=slot.load+hours;
  const clusters=slotClusterSetV11(slot),same=clusters.has(clusterId),empty=clusters.size===0;
  const nearby=!empty&&!same&&[...clusters].every(id=>clusterDistanceV9(id,clusterId)<=1);
  let score=0;
  if(projected>safe)score+=(projected-safe)*1600;
  score+=(slot.load/Math.max(1,safe))*8;
  if(same)score-=220;
  else if(empty)score+=0;
  else if(nearby)score+=220;
  else score+=720;
  const sameClusterElsewhereThatDay=slots.some(other=>other!==slot&&other.dayIndex===slot.dayIndex&&slotClusterSetV11(other).has(clusterId));
  if(sameClusterElsewhereThatDay)score-=35;
  const preferred=averagePreferredDayV11(jobs);
  score+=dayDistanceV11(slot.dayIndex,preferred)*18;
  if((slot.team.primaryClusterIds||[]).includes(clusterId))score-=24;
  if(jobs.some(job=>clientById(job.clientId)?.preferredTeamId===slot.team.id))score-=10;
  const anchor=teamDayPlanV9(slot.team.id,slot.date).primaryClusterId||'';
  if(anchor){score+=anchor===clusterId?-320:820;}
  const dayLoad=slots.filter(other=>other.dayIndex===slot.dayIndex).reduce((sum,other)=>sum+other.load,0);
  score+=dayLoad*0.8;
  return score;
}
function addJobToSlotV11(job,slot){
  job.date=slot.date;job.teamId=slot.team.id;job.clusterId=job.clusterId||clusterForJobV9(job)?.id||'';
  job.autoAssigned=true;job.manualOverride=false;
  slot.jobs.push(job);slot.load+=Number(job.estimatedHours||0);if(job.clusterId)slot.clusters.add(job.clusterId);
}
function choosePackV11(remaining,room,dayIndex){
  const ordered=[...remaining].sort((a,b)=>dayDistanceV11(dayIndexV11(clientById(a.clientId)?.preferredDay),dayIndex)-dayDistanceV11(dayIndexV11(clientById(b.clientId)?.preferredDay),dayIndex)||Number(b.estimatedHours||0)-Number(a.estimatedHours||0));
  const selected=[];let used=0;
  ordered.forEach(job=>{const hours=Number(job.estimatedHours||0);if(used+hours<=room+0.001){selected.push(job);used+=hours;}});
  if(!selected.length&&ordered.length)selected.push(ordered[0]);
  return selected;
}
function smartAssignJobsV11(jobs,dates,preserved=[]){
  const slots=[];
  dates.forEach((date,dayIndex)=>state.teams.forEach(team=>{
    const fixed=preserved.filter(job=>job.date===date&&job.teamId===team.id);
    slots.push({date,dayIndex,team,jobs:[...fixed],load:fixed.reduce((sum,job)=>sum+Number(job.estimatedHours||0),0),clusters:new Set(fixed.map(job=>clusterForJobV9(job)?.id).filter(Boolean))});
  }));
  const fixedJobs=jobs.filter(job=>clientById(job.clientId)?.fixedDay);
  const flexibleJobs=jobs.filter(job=>!clientById(job.clientId)?.fixedDay);
  fixedJobs.sort((a,b)=>Number(b.estimatedHours||0)-Number(a.estimatedHours||0)).forEach(job=>{
    const client=clientById(job.clientId),targetIndex=dayIndexV11(client?.preferredDay),clusterId=clusterForJobV9(job)?.id||'';
    const candidates=slots.filter(slot=>slot.dayIndex===targetIndex).sort((a,b)=>slotRoutingScoreV11(a,clusterId,[job],slots)-slotRoutingScoreV11(b,clusterId,[job],slots));
    addJobToSlotV11(job,candidates[0]||slots[0]);
  });
  const groups=new Map();
  flexibleJobs.forEach(job=>{const clusterId=clusterForJobV9(job)?.id||'unclustered';if(!groups.has(clusterId))groups.set(clusterId,[]);groups.get(clusterId).push(job);});
  const sortedGroups=[...groups.entries()].sort((a,b)=>b[1].reduce((sum,j)=>sum+Number(j.estimatedHours||0),0)-a[1].reduce((sum,j)=>sum+Number(j.estimatedHours||0),0));
  sortedGroups.forEach(([clusterId,groupJobs])=>{
    let remaining=[...groupJobs];
    while(remaining.length){
      const candidates=slots.map(slot=>({slot,score:slotRoutingScoreV11(slot,clusterId,remaining,slots),room:Math.max(0,safeCapacityV9(slot.team)-slot.load)})).sort((a,b)=>a.score-b.score||b.room-a.room);
      let choice=candidates.find(item=>item.room>0)||candidates[0];
      const total=remaining.reduce((sum,job)=>sum+Number(job.estimatedHours||0),0);
      if(total<=choice.room+0.001){remaining.forEach(job=>addJobToSlotV11(job,choice.slot));remaining=[];continue;}
      const pack=choosePackV11(remaining,choice.room,choice.slot.dayIndex);
      pack.forEach(job=>addJobToSlotV11(job,choice.slot));
      const ids=new Set(pack.map(job=>job.id));remaining=remaining.filter(job=>!ids.has(job.id));
    }
  });
  return slots;
}
function smartWeekSummaryV11(jobs){
  const routeKeys=new Set(jobs.map(job=>`${job.date}|${job.teamId}|${clusterForJobV9(job)?.id||''}`));
  const shifted=jobs.filter(job=>job.date!==dateAdd(startOfWeek(job.date),dayIndexV11(clientById(job.clientId)?.preferredDay))).length;
  const fixed=jobs.filter(job=>clientById(job.clientId)?.fixedDay).length;
  return {routes:routeKeys.size,shifted,fixed};
}
function generateSmartWeekV11(){
  const week=$('scheduleWeekPicker').value||startOfWeek(localDateISO()),dates=weekDates(week),dateSet=new Set(dates);
  const weekJobs=state.schedules.filter(job=>dateSet.has(job.date));
  const existingRecurringClientIds=new Set(weekJobs.filter(job=>jobRevenueTypeV9(job)==='Recurring contract').map(job=>job.clientId));
  const preserved=weekJobs.filter(job=>job.status==='completed'||job.locked||jobRevenueTypeV9(job)!=='Recurring contract');
  const preservedRecurringIds=new Set(preserved.filter(job=>jobRevenueTypeV9(job)==='Recurring contract').map(job=>job.clientId));
  const removed=weekJobs.length-preserved.length;
  state.schedules=state.schedules.filter(job=>!dateSet.has(job.date)).concat(preserved);
  const generated=[];let skipped=0;
  state.clients.filter(client=>client.status==='active').forEach(client=>{
    if(preservedRecurringIds.has(client.id))return;
    if(!clientDueInWeekV10(client,week,dates,existingRecurringClientIds.has(client.id))){skipped++;return;}
    if(!DAYS.includes(client.preferredDay)){skipped++;return;}
    generated.push({id:uid('sch'),date:'',clientId:client.id,teamId:'',clusterId:client.clusterId,status:'scheduled',estimatedHours:client.estimatedHours||1,sort:99,locked:false,revenueType:'Recurring contract',workTypeIds:[...(client.workTypeIds||[])],autoGenerated:true,manualOverride:false});
  });
  smartAssignJobsV11(generated,dates,preserved);state.schedules.push(...generated);save();renderSchedule();
  const summary=smartWeekSummaryV11(generated);
  showGenerationResultV10(`<strong>Route-first week rebuilt.</strong> ${generated.length} recurring visit${generated.length===1?'':'s'} grouped into ${summary.routes} cluster route${summary.routes===1?'':'s'}. ${summary.shifted} flexible visit${summary.shifted===1?' was':'s were'} moved away from the preferred day to reduce travel. ${summary.fixed} fixed-day visit${summary.fixed===1?' was':'s were'} protected. ${preserved.length} completed, locked or special job${preserved.length===1?' was':'s were'} kept.`);
  toast(`Smart Week grouped ${generated.length} visits into ${summary.routes} cluster routes.`);
}
function optimizeRouteFirstWeekV11(){
  const dates=weekDates($('scheduleWeekPicker').value),dateSet=new Set(dates),weekJobs=state.schedules.filter(job=>dateSet.has(job.date));
  const preserved=weekJobs.filter(job=>job.status==='completed'||job.locked||jobRevenueTypeV9(job)!=='Recurring contract');
  const movable=weekJobs.filter(job=>job.status!=='completed'&&!job.locked&&jobRevenueTypeV9(job)==='Recurring contract');
  smartAssignJobsV11(movable,dates,preserved);save();renderSchedule();
  const summary=smartWeekSummaryV11(movable);showGenerationResultV10(`<strong>Unlocked routes optimised.</strong> ${movable.length} visit${movable.length===1?'':'s'} grouped into ${summary.routes} cluster route${summary.routes===1?'':'s'} while completed, locked and special work remained unchanged.`);toast('Unlocked visits regrouped by route first, then capacity.');
}
