  const hours=jobs.reduce((sum,job)=>sum+Number(job.estimatedHours||0),0);
  const clusters=slotClusterSetV11(slot),same=clusters.has(clusterId),empty=clusters.size===0;
  const nearby=!empty&&!same&&[...clusters].every(id=>clusterDistanceV9(id,clusterId)<=1);
  const capacity=slotCapacityForClusterV13(slot,clusterId),projected=slot.load+hours;
