    const without=mask&~(1<<i);let best=solve(without);best={...best,groups:[[i],...best.groups]};
    for(let j=i+1;j<bundles.length;j++)if(mask&(1<<j)){
      if(!canMergeBundlesV131(bundles[i],bundles[j]))continue;
      const rest=solve(without&~(1<<j)),candidate={pairs:rest.pairs+1,pairedHours:rest.pairedHours+bundles[i].hours+bundles[j].hours,distance:rest.distance+routeBundleDistanceV131(bundles[i],bundles[j]),groups:[[i,j],...rest.groups]};
      const better=candidate.pairs>best.pairs||candidate.pairs===best.pairs&&candidate.pairedHours>best.pairedHours+0.001||candidate.pairs===best.pairs&&Math.abs(candidate.pairedHours-best.pairedHours)<0.001&&candidate.distance<best.distance;
      if(better)best=candidate;
    }
    memo.set(mask,best);return best;
