  const existing=slotClusterSetV11(slot),same=[...bundle.clusterIds].every(id=>existing.has(id)),empty=existing.size===0,near=!empty&&[...bundle.clusterIds].every(id=>[...existing].every(x=>clusterDistanceV9(x,id)<=1));
