  if(existing){toast('This catch-up has already been scheduled.','error');return;}
  const newJob={...source,id:uid('sch'),date,teamId,status:'scheduled',sort:99,manualOverride:true,autoGenerated:false,linkedFromJobId:source.id,catchUpId:item.id,audit:[{at:new Date().toISOString(),actor:'Office',action:'Catch-up scheduled',note:`From ${source.date}`} ]};
