  const date=$('missingWorkRecordDate').value,teamId=$('missingWorkRecordTeam').value,hours=Number($('missingWorkRecordHours').value||0),tasks=String($('missingWorkRecordTasks').value||'').split(/\n+/).map(value=>value.trim()).filter(Boolean);
