    <div class="single-team-job-side"><strong>${Number(job.estimatedHours||0).toFixed(1)}h</strong><small>${esc(shortRevenueLabelV17(jobRevenueTypeV9(job)))}</small>${completed?'<span class="status-badge paid">Done</span>':`<button type="button" class="button secondary compact" onclick="openMoveJobV20('${job.id}')">Move</button>`}</div>
