      const cell=scheduleCellStateV20(team,date,jobs),rows=cell.rows.sort((a,b)=>routeOrderV14(a)-routeOrderV14(b)),blocked=cell.full,drop=blocked?'':`ondragover="event.preventDefault()" ondrop="dropSchedule(event,'${date}','${team.id}')"`;
      return `<section class="single-team-day ${cell.over?'over':cell.full?'full':''}" ${drop}><div class="single-team-day-head"><div><strong>${DAYS[index]}</strong><span>${fmtShortDate(date)}</span></div><small>${cell.used.toFixed(1)} / ${cell.safe.toFixed(1)}h${cell.over?' · OVER':cell.full?' · FULL':''}</small></div><div class="single-team-job-list">${rows.map(singleTeamJobV20).join('')||'<div class="single-team-empty">No jobs assigned</div>'}</div></section>`;
