  $('moveScheduleJobId').value=job.id;$('moveScheduleJobSummary').textContent=`${client.name} — ${client.address||client.suburb||''}`;$('moveScheduleJobDate').innerHTML=moveJobDateOptionsV20(job.date);$('moveScheduleJobTeam').innerHTML=state.teams.map(team=>`<option value="${team.id}" ${team.id===job.teamId?'selected':''}>${esc(team.name)}</option>`).join('');updateMoveCapacityV20();$('moveScheduleJobDialog').showModal();
