/* Business Overview */
const BUSINESS_WORK_TYPES_V23=['Recurring contract','Existing-client add-on','Direct once-off project','Subcontract job'];
function endOfMonthV23(month){const [year,number]=month.split('-').map(Number);return localDateISO(new Date(year,number,0));}
function daysBetweenV23(a,b){return Math.max(1,Math.round((new Date(`${b}T12:00:00`)-new Date(`${a}T12:00:00`))/86400000)+1);}
function businessPeriodV23(){
  const mode=$('overviewPeriodMode')?.value||'this-month',today=localDateISO(),month=currentMonth();let start=`${month}-01`,end=today,label=monthLabel(month);
  if(mode==='last-month'){const previous=monthShift(month,-1);start=`${previous}-01`;end=endOfMonthV23(previous);label=monthLabel(previous);}
  else if(mode==='last-3'){const first=monthShift(month,-2);start=`${first}-01`;end=today;label=`${monthLabel(first)} to ${fmtDate(today)}`;}
  else if(mode==='ytd'){start=`${today.slice(0,4)}-01-01`;end=today;label=`Year to date · ${today.slice(0,4)}`;}
  else if(mode==='custom'){start=$('overviewStartDate')?.value||start;end=$('overviewEndDate')?.value||end;if(start>end)[start,end]=[end,start];label=`${fmtDate(start)} to ${fmtDate(end)}`;}
  return {mode,start,end,label};
}
