  const categories={};opportunities.forEach(item=>{const category=item.category||classifyOpportunityCategoryV23(`${item.note||''} ${item.description||''}`);categories[category]=(categories[category]||0)+1;});quotes.forEach(quote=>{const category=classifyOpportunityCategoryV23((quote.lineItems||[]).map(line=>line.description).join(' '));categories[category]=(categories[category]||0)+1;});
