allTeamCalendarCellV24=function(team,date,jobs){
  const cell=scheduleCellStateV20(team,date,jobs),rows=[...cell.rows].sort((a,b)=>routeOrderV14(a)-routeOrderV14(b));
  const {area,suburbs}=scheduleCellAreaV23(rows),past=isPastScheduleDateV23(date),movable=!past&&rows.some(job=>job.status!=='completed');
  const overBy=Math.max(0,cell.used-cell.safe),available=Math.max(0,cell.safe-cell.used),stateLabel=past?'Frozen':cell.over?`Over ${overBy.toFixed(1)}h`:cell.full?'Full':rows.length?`${available.toFixed(1)}h free`:'Available',stateClass=past?'past-label':cell.over?'over-label':cell.full?'full-label':'available-label';
  const dragAttrs=movable?`draggable="true" ondragstart="dragScheduleRouteV24(event,'${team.id}','${date}')" ondragend="endScheduleRouteDragV24(event)"`:'';
  return `<div class="calendar-team-day v24 v25 ${past?'past':cell.over?'over':cell.full?'full':'can-drop'} ${rows.length?'has-route':'empty-route'} ${selectedScheduleDetailV23?.mode==='day'&&selectedScheduleDetailV23.teamId===team.id&&selectedScheduleDetailV23.date===date?'selected':''}" ${scheduleCellDropAttrsV24(team,date)} ${dragAttrs} aria-label="${esc(team.name)} ${dayName(date)}: ${rows.length} jobs, ${stateLabel}" title="${movable?'Drag this route to another team-day':'Route details'}"><div class="route-cell-heading"><div class="calendar-cell-location ${rows.length?'':'empty'}">${rows.length?`<span>Working in</span><strong>${esc(area)}</strong>`:`<strong>${past?'No route':'Available'}</strong>`}</div>${rows.length?`<button type="button" class="route-detail-toggle" draggable="false" onclick="event.stopPropagation();openScheduleDayV24('${team.id}','${date}')" aria-label="Open ${esc(team.name)} ${dayName(date)} route">Details <span>⌄</span></button>`:''}</div><div class="calendar-cell-summary"><strong>${rows.length} job${rows.length===1?'':'s'}</strong><span>${cell.used.toFixed(1)} / ${cell.safe.toFixed(1)}h</span></div><div class="calendar-capacity-badge ${stateClass}">${stateLabel}</div>${suburbs.length?`<div class="calendar-suburbs" title="${esc(suburbs.join(', '))}">${esc(suburbs.slice(0,2).join(' · '))}${suburbs.length>2?` · +${suburbs.length-2}`:''}</div>`:''}${movable?'<div class="route-drag-hint"><span>⋮⋮</span> Drag route</div>':''}</div>`;
};
