  if(onboardingStepV27===3)fields=[$('onboardingClusterName'),$('onboardingSuburbs')];
  const invalid=fields.find(field=>!field||!String(field.value||'').trim()||(field.type==='number'&&Number(field.value)<=0));
  if(invalid){invalid.focus();$('onboardingError').textContent='Complete the required fields before continuing.';return false;}
  $('onboardingError').textContent='';return true;
