  $('onboardingLeaderName').value=primaryTeam.leaderName||'';
  $('onboardingDailySites').value=primaryTeam.dailySiteCapacity?Number(primaryTeam.dailySiteCapacity):'';
  $('onboardingClusterName').value=primaryCluster.name||'';
  $('onboardingSuburbs').value=(primaryCluster.suburbs||[]).join(', ');
  $('onboardingClusterColor').value=primaryCluster.color||'#2e8b68';
  const choice=state.onboarding?.clientSetupChoice||'manual';
