  const now=new Date().toISOString(),b=state.business;
  Object.assign(b,{
    name:$('onboardingBusinessName').value.trim(),phone:$('onboardingPhone').value.trim(),
    email:$('onboardingEmail').value.trim(),address:$('onboardingAddress').value.trim(),
    emailSenderName:$('onboardingBusinessName').value.trim(),
    sendingEmail:$('onboardingEmail').value.trim(),replyTo:$('onboardingEmail').value.trim()
  });
  let team=teamById(state.onboarding?.primaryTeamId)||state.teams[0];
  if(!team){team={id:uid('team'),name:'',leaderName:'',capacityHours:8,bufferHours:1,serviceArea:'',primaryClusterIds:[]};state.teams.push(team);}
  Object.assign(team,{name:$('onboardingTeamName').value.trim(),leaderName:$('onboardingLeaderName').value.trim(),dailySiteCapacity:Number($('onboardingDailySites').value),capacityHours:Number(team.capacityHours||8),bufferHours:Number(team.bufferHours??1)});
  let cluster=clusterByIdV9(state.onboarding?.primaryClusterId)||state.clusters[0];
  if(!cluster){cluster={id:uid('cluster'),name:'',color:'#2e8b68',suburbs:[],neighborIds:[],active:true};state.clusters.push(cluster);}
  Object.assign(cluster,{name:$('onboardingClusterName').value.trim(),color:$('onboardingClusterColor').value||'#2e8b68',suburbs:String($('onboardingSuburbs').value||'').split(',').map(value=>value.trim()).filter(Boolean),active:true});
  team.primaryClusterIds=[cluster.id];team.serviceArea=cluster.name;
  const choice=document.querySelector('input[name="onboardingClientChoice"]:checked')?.value||'later';
  state.onboarding={...(state.onboarding||{}),completedAt:now,primaryTeamId:team.id,primaryClusterId:cluster.id,clientSetupChoice:choice};
  state.onboardingComplete=true;state.version=27;
  save();populateTeamSelectsV9();$('businessNameHeader').textContent=b.name||'TuinBooks';$('onboardingDialog').close();
  showView('clients');renderClients();
