/* ---------- v59.4.8 bounded authentication startup ----------
   Supabase session restoration must never leave the application on the logo
   splash forever. Every auth.getSession() call now has a finite timeout and
   one clear failure path. */
const TUINBOOKS_AUTH_STARTUP_V59480='59.4.8-bounded-auth-startup';
async function getAuthSessionResultV59480(client,timeoutMs=12000){
  if(!client?.auth?.getSession)throw new Error('TuinBooks authentication is not available.');
  let timer;
  try{
    return await Promise.race([
      Promise.resolve(client.auth.getSession()),
      new Promise((_,reject)=>{
        timer=setTimeout(()=>{
          const error=new Error('TuinBooks could not restore the secure browser session within 12 seconds. Close any older TuinBooks tabs, then reload this page.');
          error.code='AUTH_SESSION_TIMEOUT';
          reject(error);
        },Math.max(3000,Number(timeoutMs)||12000));
      })
    ]);
  }finally{clearTimeout(timer);}
}
window.getAuthSessionResultV59480 = getAuthSessionResultV59480; // v59.6.91 cross-wrapper scope export

