    state.clusters=(clusters||[]).map(row=>({...row.payload,id:row.id,name:row.name,color:row.color,suburbs:row.suburbs||[],active:row.active}));
    const siteMap=new Map();(sites||[]).forEach(site=>{const current=siteMap.get(site.customer_id);if(!current||(site.active!==false&&current.active===false))siteMap.set(site.customer_id,site);});
