async function loadWorkspaceV28(businessId){
  const client=backendV28.client;
  if(backendV28.role==='field'){
    const {data,error}=await client.rpc('load_field_workspace_v54',{p_business_id:businessId});
    if(error)throw error;
    hydrateWorkspaceStateV28(data?.business,data?.teams||[],data?.clusters||[],data?.customers||[],data?.sites||[]);
    return;
  }
  const results=await Promise.all([
    client.from('businesses').select('id,name,phone,email,address,settings,onboarding_complete,core_revision').eq('id',businessId).single(),
    client.from('teams').select('id,name,leader_name,capacity_hours,buffer_hours,active,payload,created_at').eq('business_id',businessId).order('created_at'),
    client.from('clusters').select('id,name,color,suburbs,active,payload,created_at').eq('business_id',businessId).order('created_at'),
    client.from('customers').select('id,name,customer_type,contact_name,email,phone,external_accounting_id,status,billing_profile_id,payload,created_at').eq('business_id',businessId).order('created_at'),
    client.from('service_sites').select('id,customer_id,address,suburb,cluster_id,access_notes,pet_notes,instructions,active,payload,created_at').eq('business_id',businessId).order('created_at')
  ]);
  const failed=results.find(result=>result.error);if(failed)throw failed.error;
  hydrateWorkspaceStateV28(results[0].data,results[1].data,results[2].data,results[3].data,results[4].data);
}
