/* ---------- v30 users, invitations and team assignments ---------- */
const TUINBOOKS_VERSION_V30=30;
const INVITE_PARAM_V30='invite';
backendV28.assignedTeamIds=[];
backendV28.users=[];
backendV28.invites=[];
backendV28.inviteToken='';

function appRootUrlV30(){
  const url=new URL(window.location.href);
  const path=url.pathname;
  const slash=path.lastIndexOf('/');
  return `${url.origin}${path.slice(0,slash+1)}`;
}
function invitationTokenV30(){
  const value=new URLSearchParams(window.location.search).get(INVITE_PARAM_V30)||'';
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)?value:'';
}
function removeInvitationTokenV30(){
  const url=new URL(window.location.href);url.searchParams.delete(INVITE_PARAM_V30);
  window.history.replaceState({},'',`${url.pathname}${url.search}${url.hash}`);
}
function invitationLinkV30(invite){
  const target=invite.role==='field'?'mobile.html':'';
  return `${appRootUrlV30()}${target}?${INVITE_PARAM_V30}=${encodeURIComponent(invite.token)}`;
}
function backendIsAdminV30(){return ['owner','admin'].includes(backendV28.role);}
function fmtDateTimeV30(value){
  if(!value)return '—';
  const date=new Date(value);if(Number.isNaN(date.getTime()))return '—';
  return date.toLocaleString('en-ZA',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
}
function roleLabelV30(role){return role==='owner'?'Owner':role==='admin'?'Admin':'Field user';}

const backendErrorMessageBaseV30=backendErrorMessageV28;
backendErrorMessageV28=function(error){
  const text=String(error?.message||error||'');
  if(/create_business_invite|accept_business_invite|list_business_users|team_assignments|business_invites|Could not find the function/i.test(text))return 'Users & Teams setup is incomplete. Install the latest TuinBooks database update, then refresh the page.';
  if(/same email address/i.test(text))return 'Sign in with the exact email address used in the invitation.';
  return backendErrorMessageBaseV30(error);
};

const setBackendAuthModeBaseV30=setBackendAuthModeV28;
setBackendAuthModeV28=function(mode){
  const app=document.body.dataset.app,token=invitationTokenV30();
  if(app==='mobile'&&!token&&mode==='signup')mode='signin';
  setBackendAuthModeBaseV30(mode);
  const signupButton=document.querySelector('[data-backend-auth-mode="signup"]');
  if(signupButton)signupButton.classList.toggle('hidden',app==='mobile'&&!token);
  if(token){
    if($('backendAuthTitle'))$('backendAuthTitle').textContent=backendV28.authMode==='signup'?'Create your invited account':'Accept your TuinBooks invitation';
    if($('backendAuthHelp'))$('backendAuthHelp').textContent='Use the exact email address the office invited. After sign-in, TuinBooks assigns your role and team automatically.';
  }else if(app==='mobile'){
    if($('backendAuthTitle'))$('backendAuthTitle').textContent='Field team sign in';
    if($('backendAuthHelp'))$('backendAuthHelp').textContent='Use the field account created for this team. New field users need an access link from the office.';
  }
};

submitBackendAuthV28=async function(event){
  event.preventDefault();if(!backendV28.client)return showBackendConnectionV28('TuinBooks is not ready yet. Please contact your administrator.');
  const email=$('backendAuthEmail')?.value.trim()||'',password=$('backendAuthPassword')?.value||'',displayName=$('backendDisplayName')?.value.trim()||'',passwordConfirm=$('backendAuthPasswordConfirm')?.value||'';
  if(backendV28.authMode==='signup'&&password!==passwordConfirm){if($('backendAuthMessage'))$('backendAuthMessage').textContent='The passwords do not match.';return;}
  const button=$('backendAuthSubmit'),original=button?.textContent||'';if(button){button.disabled=true;button.textContent=backendV28.authMode==='signup'?'Creating…':'Signing in…';}
  if($('backendAuthMessage'))$('backendAuthMessage').textContent='';
  try{
    if(backendV28.authMode==='signup'){
      const token=invitationTokenV30();
      const redirect=new URL(window.location.href);redirect.hash='';
      const options={data:{display_name:displayName}};
      options.emailRedirectTo=redirect.toString();
      const {data,error}=await backendV28.client.auth.signUp({email,password,options});if(error)throw error;
      if(data.session)await handleAuthenticatedV28(data.session);
      else if($('backendAuthMessage'))$('backendAuthMessage').textContent=token?'Account created. You can close this page now. Open the TuinBooks confirmation email and use the link in that email to finish joining your team.':'Account created. You can close this page now. Open the TuinBooks confirmation email and use the link in that email to continue.';
    }else{
      const {data,error}=await backendV28.client.auth.signInWithPassword({email,password});if(error)throw error;
      await handleAuthenticatedV28(data.session);
    }
  }catch(error){if($('backendAuthMessage'))$('backendAuthMessage').textContent=backendErrorMessageV28(error);}
  finally{if(button){button.disabled=false;button.textContent=original;}}
};

async function acceptInvitationV30(token){
  if(!token)return null;
  const {data,error}=await backendV28.client.rpc('accept_business_invite',{p_token:token});
  if(error)throw error;
  return Array.isArray(data)?data[0]:data;
}
async function loadMyTeamAssignmentsV30(businessId,userId){
  const {data,error}=await backendV28.client.from('team_assignments').select('team_id,is_primary,active').eq('business_id',businessId).eq('user_id',userId).eq('active',true);
  if(error)throw error;
  return (data||[]).sort((a,b)=>Number(b.is_primary)-Number(a.is_primary)).map(row=>row.team_id).filter(Boolean);
}
const TUINBOOKS_VERSION_V44_PORTAL_ROUTING=true;
function routeForRoleV30(role){
  const app=document.body.dataset.app;
  // Field users are always kept in the mobile workspace.
  if(role==='field'&&app==='desktop'){
    window.location.replace(`${appRootUrlV30()}mobile.html`);return true;
  }
  // Owners and admins may deliberately use either URL. This lets the office
  // test or operate the field view without being forced back to desktop.
  return false;
}

const SUPPORT_MODE_V5935=new URLSearchParams(window.location.search).get('support')==='1';
function supportRequestedBusinessV5935(){return new URLSearchParams(window.location.search).get('business')||'';}
function supportRowV5935(value){return Array.isArray(value)?(value[0]||null):(value||null);}
function supportCanEditV5935(ctx){return !!(ctx?.operational_edit??ctx?.allow_operational_edit)||!!(ctx?.financial_edit??ctx?.allow_financial_edit);}
function supportCanReadV5935(ctx){return supportCanEditV5935(ctx)||!!(ctx?.operational_read??ctx?.allow_operational_read)||!!(ctx?.financial_read??ctx?.allow_financial_read);}
function renderManagementBannerV5935(ctx){
  if(!ctx||document.body.dataset.app!=='desktop')return;
  let style=document.getElementById('managementModeStyleV5935');
  if(!style){
    style=document.createElement('style');style.id='managementModeStyleV5935';
    style.textContent='#managementModeBannerV5935{position:sticky;top:0;z-index:2147483000;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:9px 18px;background:#173f2d;color:#fff;font:700 14px/1.25 system-ui,sans-serif;box-shadow:0 2px 10px rgba(0,0,0,.16)}#managementModeBannerV5935 small{font-weight:500;opacity:.84}#managementModeBannerV5935 button{border:1px solid rgba(255,255,255,.5);border-radius:9px;background:#fff;color:#173f2d;padding:7px 11px;font-weight:800;cursor:pointer}@media(max-width:700px){#managementModeBannerV5935{align-items:flex-start;flex-direction:column}}';
    document.head.appendChild(style);
  }
  let banner=document.getElementById('managementModeBannerV5935');
  if(!banner){banner=document.createElement('section');banner.id='managementModeBannerV5935';document.body.prepend(banner);}
  const businessName=ctx.business_name||state?.business?.name||'Client account';
  const edit=supportCanEditV5935(ctx);
  banner.innerHTML=`<div>MANAGEMENT MODE — ${esc(businessName)}<br><small>${edit?'Full setup access':'Read-only access'} · your management identity is recorded</small></div><button type="button" id="returnToManagementV5935">Return to Management</button>`;
  document.getElementById('returnToManagementV5935')?.addEventListener('click',async()=>{
    try{if(ctx.session_id)await backendV28.client.rpc('tuinbooks_end_support_session',{p_session_id:ctx.session_id});}catch(error){console.warn('Could not end management session',error);}
    window.location.replace('../management/');
  },{once:true});
  document.title=`${businessName} — TuinBooks Management`;
}
async function loadManagementWorkspaceV5935(session){
  setBackendLoadingV28('Opening the selected client account…');
  const {data,error}=await backendV28.client.rpc('tuinbooks_current_support_context');
  if(error)throw error;
  const ctx=supportRowV5935(data);
  const requested=supportRequestedBusinessV5935();
  if(!ctx?.business_id)throw new Error('No active management session was found. Return to Management and open the account again.');
  if(requested&&String(ctx.business_id)!==String(requested))throw new Error('The active management session belongs to a different client. Return to Management and open the correct account again.');
  if(!supportCanReadV5935(ctx))throw new Error('This management session has no readable account access.');

  backendV28.session=session;
  backendV28.user=session.user;
  backendV28.mode='supabase';
  backendV28.businessId=ctx.business_id;
  backendV28.role=supportCanEditV5935(ctx)?'owner':'support';
  backendV28.displayName=ctx.support_display_name||session.user.user_metadata?.display_name||session.user.email||'TuinBooks Management';
  backendV28.assignedTeamIds=[];
  backendV28.handlingUserId=session.user.id;
  backendV28.allowOnboarding=supportCanEditV5935(ctx);
  backendV28.supportContext=ctx;
  window.__TUINBOOKS_MANAGEMENT_CONTEXT_V5935__=ctx;

  await loadWorkspaceV28(ctx.business_id);
  backendV28.businessId=ctx.business_id;
  backendV28.role=supportCanEditV5935(ctx)?'owner':'support';
  backendV28.allowOnboarding=supportCanEditV5935(ctx);
  backendV28.coreDirty=false;
  backendV28.operationalDirty=false;
  backendV28.pendingSnapshot=null;
  backendV28.operationalPendingSnapshot=null;
  hideBackendGateV28();
  refreshAppAfterCloudLoadV28();
  setBackendSyncStateV28(supportCanEditV5935(ctx)?'Management setup access':'Management read-only','saved');
  if($('onboardingDialog')?.open)$('onboardingDialog').close();
  renderManagementBannerV5935(ctx);
}

handleAuthenticatedV28=async function(session){
  if(!session?.user)return showBackendAuthV28();
  if(SUPPORT_MODE_V5935){
    try{await loadManagementWorkspaceV5935(session);return;}
    catch(error){
      backendV28.handlingUserId='';backendV28.businessId=null;backendV28.assignedTeamIds=[];
      showBackendAuthV28(`Management access failed: ${backendErrorMessageV28(error)}`);return;
    }
  }
  if(backendV28.handlingUserId===session.user.id&&backendV28.businessId)return;
  backendV28.session=session;backendV28.user=session.user;backendV28.mode='supabase';
  backendV28.displayName=session.user.user_metadata?.display_name||session.user.email||'';
  setBackendLoadingV28('Checking your role and assigned team…');
  try{
    const token=invitationTokenV30();
    if(token)await acceptInvitationV30(token);
    const requestedBusinessIdV59326=new URLSearchParams(location.search).get('business')||'';
    let membershipQueryV59326=backendV28.client.from('business_members').select('business_id,role,display_name,active').eq('user_id',session.user.id).eq('active',true);
    if(/^[0-9a-f-]{36}$/i.test(requestedBusinessIdV59326))membershipQueryV59326=membershipQueryV59326.eq('business_id',requestedBusinessIdV59326);
    const {data:membership,error}=await membershipQueryV59326.maybeSingle();
    if(error)throw error;
    backendV28.businessId=membership?.business_id||null;
    backendV28.role=membership?.role||null;
    backendV28.displayName=membership?.display_name||backendV28.displayName;
    backendV28.assignedTeamIds=backendV28.businessId?await loadMyTeamAssignmentsV30(backendV28.businessId,session.user.id):[];
    backendV28.handlingUserId=session.user.id;

    if(backendV28.businessId){
      if(token)removeInvitationTokenV30();
      if(routeForRoleV30(backendV28.role))return;
      await loadWorkspaceV28(backendV28.businessId);
      backendV28.allowOnboarding=backendIsAdminV30();hideBackendGateV28();refreshAppAfterCloudLoadV28();setBackendSyncStateV28('Workspace ready','saved');
      if(document.body.dataset.app==='desktop'){
        if(state.onboardingComplete){if($('onboardingDialog')?.open)$('onboardingDialog').close();}
        else requestAnimationFrame(()=>openOnboardingV27(true));
      }
      return;
    }

    backendV28.hydrating=true;state=seedState();state.version=TUINBOOKS_VERSION_V30;saveLocalBaseV28();backendV28.hydrating=false;
    if(document.body.dataset.app==='mobile'){
      backendV28.handlingUserId='';
      showBackendAuthV28(token?'This invitation could not be accepted. Check the email address or ask the office for a new link.':'This account has no active field access. Ask the office to create an access link.');
      return;
    }
    if(token){backendV28.handlingUserId='';showBackendAuthV28('This invitation could not be accepted. Check the email address or ask the office for a new link.');return;}
    backendV28.role='owner';backendV28.allowOnboarding=true;hideBackendGateV28();refreshAppAfterCloudLoadV28();setBackendSyncStateV28('Account ready','saved');requestAnimationFrame(()=>openOnboardingV27(true));
  }catch(error){
    backendV28.handlingUserId='';backendV28.businessId=null;backendV28.assignedTeamIds=[];
    showBackendAuthV28(backendErrorMessageV28(error));
  }
};

