async function loadBusinessUsersV30(){
  if(!backendV28.client||!backendV28.businessId||!backendIsAdminV30())return {users:[],invites:[]};
  const [userResult,inviteResult]=await Promise.all([
    backendV28.client.rpc('list_business_users',{p_business_id:backendV28.businessId}),
    backendV28.client.rpc('list_business_invites',{p_business_id:backendV28.businessId})
  ]);
  if(userResult.error)throw userResult.error;if(inviteResult.error)throw inviteResult.error;
  backendV28.users=userResult.data||[];backendV28.invites=inviteResult.data||[];
  return {users:backendV28.users,invites:backendV28.invites};
}
function businessUserRowHtmlV30(user){
  const current=backendV28.user?.id===user.user_id;
  const actions=user.role==='owner'?'':`<button type="button" class="button secondary compact" onclick="openBusinessUserDialogV30('${user.user_id}')">Edit</button>`;
  return `<article class="business-user-row ${user.active?'':'disabled'}"><div class="business-user-main"><strong>${esc(user.display_name||user.email||'User')}${current?' (you)':''}</strong><span>${esc(user.email||'')}</span></div><div class="business-user-cell"><span class="user-role-badge ${user.role==='field'?'field':''}">${esc(roleLabelV30(user.role))}</span><span class="user-status-dot ${user.active?'':'disabled'}">${user.active?'Active':'Disabled'}</span></div><div class="business-user-cell"><strong>${esc(user.team_name||(user.role==='field'?'No team assigned':'All teams'))}</strong><span>${user.last_sign_in_at?`Last sign-in ${esc(fmtDateTimeV30(user.last_sign_in_at))}`:'Not signed in yet'}</span></div><div class="business-user-actions">${actions}</div></article>`;
}
function businessInviteRowHtmlV30(invite){
  const active=invite.status==='pending'&&new Date(invite.expires_at)>new Date();
  const link=invitationLinkV30(invite);
  return `<article class="business-invite-row"><div class="business-invite-main"><strong>${esc(invite.display_name||invite.email)}</strong><span>${esc(invite.email)}</span></div><div class="business-invite-cell"><span class="user-role-badge ${invite.role==='field'?'field':''}">${esc(roleLabelV30(invite.role))}</span><span>${esc(invite.team_name||(invite.role==='field'?'No team':'Desktop access'))}</span></div><div class="business-invite-cell"><strong>${esc(invite.status)}</strong><span>${active?`Expires ${esc(fmtDateTimeV30(invite.expires_at))}`:esc(fmtDateTimeV30(invite.created_at))}</span></div><div class="business-invite-actions">${active?`<button type="button" class="button secondary compact" onclick="copyTextV30('${esc(link)}','Access link copied.')">Copy link</button><button type="button" class="button danger secondary compact" onclick="revokeBusinessInviteV30('${invite.invite_id}')">Revoke</button>`:''}</div></article>`;
}
async function renderBusinessAccessV30(){
  const status=$('businessUsersStatus'),usersHost=$('businessUsersList'),invitesHost=$('businessInvitesList'),addButton=$('addBusinessUserBtn');
  if(!status||!usersHost||!invitesHost)return;
  if(backendV28.mode!=='supabase'){
    status.innerHTML='<strong>Online access is unavailable.</strong> Please contact your TuinBooks administrator.';usersHost.innerHTML='';invitesHost.innerHTML='';if(addButton)addButton.disabled=true;return;
  }
  if(!backendIsAdminV30()){
    status.innerHTML='<strong>Admin access required.</strong> Only owners and admins can manage users.';usersHost.innerHTML='';invitesHost.innerHTML='';if(addButton)addButton.disabled=true;return;
  }
  if(addButton)addButton.disabled=false;status.textContent='Loading users and access links…';
  try{
    const {users,invites}=await loadBusinessUsersV30();
    status.innerHTML=`<strong>${users.filter(user=>user.active).length} active user${users.filter(user=>user.active).length===1?'':'s'}.</strong> Field accounts open the mobile app and are locked to their assigned team.`;
    usersHost.innerHTML=users.length?users.map(businessUserRowHtmlV30).join(''):'<div class="business-user-empty">No users found.</div>';
    const relevant=invites.filter(invite=>['pending','accepted','revoked','expired'].includes(invite.status)).slice(0,12);
    invitesHost.innerHTML=relevant.length?relevant.map(businessInviteRowHtmlV30).join(''):'<div class="business-user-empty">No access links have been created.</div>';
  }catch(error){status.innerHTML=`<strong>Could not load users.</strong> ${esc(backendErrorMessageV28(error))}`;usersHost.innerHTML='';invitesHost.innerHTML='';}
}
