window.openBusinessUserDialogV30=function(userId=''){
  const dialog=$('businessUserDialog');if(!dialog)return;
  const user=(backendV28.users||[]).find(row=>row.user_id===userId)||null;
  $('businessUserId').value=user?.user_id||'';$('businessUserDisplayName').value=user?.display_name||'';$('businessUserEmail').value=user?.email||'';$('businessUserEmail').readOnly=!!user;
  $('businessUserRole').value=user?.role==='admin'?'admin':'field';$('businessUserActive').checked=user?.active!==false;
  populateBusinessUserTeamOptionsV30(user?.team_id||'');updateBusinessUserTeamVisibilityV30();
  $('businessUserActiveWrap').classList.toggle('hidden',!user);$('businessUserInviteHelp').classList.toggle('hidden',!!user);
  $('businessUserDialogTitle').textContent=user?'Edit user access':'Create access link';$('saveBusinessUserBtn').textContent=user?'Save access':'Create link';$('businessUserError').textContent='';dialog.showModal();
};
function closeBusinessUserDialogV30(){$('businessUserDialog')?.close();}
async function submitBusinessUserV30(event){
  event.preventDefault();if(!backendV28.client||!backendV28.businessId)return;
  const userId=$('businessUserId').value,displayName=$('businessUserDisplayName').value.trim(),email=$('businessUserEmail').value.trim(),role=$('businessUserRole').value,teamId=role==='field'?$('businessUserTeam').value:null,active=$('businessUserActive').checked;
  const button=$('saveBusinessUserBtn'),original=button.textContent;button.disabled=true;button.textContent=userId?'Saving…':'Creating…';$('businessUserError').textContent='';
  try{
    if(role==='field'&&!teamId)throw new Error('Choose the team assigned to this field user.');
    if(userId){
      const {error}=await backendV28.client.rpc('update_business_user',{p_business_id:backendV28.businessId,p_user_id:userId,p_display_name:displayName,p_role:role,p_team_id:teamId,p_active:active});if(error)throw error;
      closeBusinessUserDialogV30();toast('User access updated.');
    }else{
      const {data,error}=await backendV28.client.rpc('create_business_invite',{p_business_id:backendV28.businessId,p_email:email,p_display_name:displayName,p_role:role,p_team_id:teamId});if(error)throw error;
      const row=Array.isArray(data)?data[0]:data,invite={token:row.invite_token,role:row.invite_role};
      closeBusinessUserDialogV30();$('generatedInviteLink').value=invitationLinkV30(invite);$('inviteLinkDialog').showModal();
    }
    await renderBusinessAccessV30();
    if(typeof renderFieldDevicesV56==='function')await renderFieldDevicesV56();
  }catch(error){$('businessUserError').textContent=backendErrorMessageV28(error);}
  finally{button.disabled=false;button.textContent=original;}
}
window.copyTextV30=async function(text,message='Copied.'){
  try{await navigator.clipboard.writeText(text);toast(message);}catch(error){const area=document.createElement('textarea');area.value=text;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove();toast(message);}
};
window.revokeBusinessInviteV30=async function(inviteId){
  if(!window.confirm('Revoke this access link? It will stop working immediately.'))return;
  try{const {error}=await backendV28.client.rpc('revoke_business_invite',{p_business_id:backendV28.businessId,p_invite_id:inviteId});if(error)throw error;toast('Access link revoked.');await renderBusinessAccessV30();}catch(error){toast(backendErrorMessageV28(error),'error');}
};

const renderSettingsBaseV30=renderSettings;
renderSettings=function(){renderSettingsBaseV30();renderBusinessAccessV30();};

function bindBackendControlsV30(){
  $('backendAuthForm')?.addEventListener('submit',submitBackendAuthV28);
  qsa('[data-backend-auth-mode]').forEach(button=>button.addEventListener('click',()=>setBackendAuthModeV28(button.dataset.backendAuthMode)));
}

document.addEventListener('DOMContentLoaded',()=>{
  const app=document.body.dataset.app;
  if(app==='desktop'){
    $('addBusinessUserBtn')?.addEventListener('click',()=>openBusinessUserDialogV30());
    $('businessUserForm')?.addEventListener('submit',submitBusinessUserV30);
    $('businessUserRole')?.addEventListener('change',updateBusinessUserTeamVisibilityV30);
    $('closeBusinessUserDialog')?.addEventListener('click',closeBusinessUserDialogV30);
    $('cancelBusinessUserDialog')?.addEventListener('click',closeBusinessUserDialogV30);
    $('closeInviteLinkDialog')?.addEventListener('click',()=>$('inviteLinkDialog')?.close());
    $('closeInviteLinkBtn')?.addEventListener('click',()=>$('inviteLinkDialog')?.close());
    $('copyInviteLinkBtn')?.addEventListener('click',()=>copyTextV30($('generatedInviteLink').value,'Access link copied.'));
    if(invitationTokenV30())setBackendAuthModeV28('signin');
    return;
  }
  if(app==='mobile'){
    bindBackendControlsV30();
    setBackendAuthModeV28('signin');
    initBackendV28();
  }
});


/* ---------- v40 client reporting alerts and communication preferences ---------- */
const TUINBOOKS_VERSION_V40=40;
const CORPORATE_CUSTOMER_TYPES_V40=['Body corporate / estate','Property manager / landlord','Commercial business','Contractor / subcontract principal'];
const CLIENT_REPORT_TYPES_V40={daily:'Daily completion email',weekly:'Weekly work summary',monthly:'Monthly work summary'};
function defaultClientCommunicationsV40(){
  return {
    visitCompleteTemplate:'Hi {client_name}, the garden service at {site_address} was completed today by {team_name}. Thank you.',
    corporateDailyTemplate:'Please find today\'s garden-service report below.',
    corporateWeeklyTemplate:'Please find the weekly garden-service summary below.',
    corporateMonthlyTemplate:'Please find the monthly garden-service summary below.',
    corporateReportSignature:'Kind regards,\n{business_name}'
  };
}
function ensureReportingStateV40(){
  state.clientReports=Array.isArray(state.clientReports)?state.clientReports:[];
  state.business=state.business||{};
  state.business.clientCommunications={...defaultClientCommunicationsV40(),...(state.business.clientCommunications||{})};
  (state.clients||[]).forEach(client=>{
    if(!client.communicationPreference)client.communicationPreference=client.email?'Email':'WhatsApp';
    if(client.completionReport===undefined)client.completionReport='yes';
    const corporate=CORPORATE_CUSTOMER_TYPES_V40.includes(client.customerType||'');
    client.reporting={daily:false,weekly:false,monthly:false,recipients:client.email||'',cc:'',grouping:'combined',includeIncomplete:'yes',includeExtras:'yes',notes:'',...(client.reporting||{})};
    if(corporate&&!client.reporting.recipients&&client.email)client.reporting.recipients=client.email;
  });
}
function isCorporateClientV40(client){return CORPORATE_CUSTOMER_TYPES_V40.includes(client?.customerType||'');}
function clientReportingEnabledV40(client,type){return isCorporateClientV40(client)&&client.status!=='archived'&&!!client.reporting?.[type];}
function dateBetweenV40(date,start,end){const d=String(date||'').slice(0,10);return !!d&&d>=start&&d<=end;}
function endOfMonthV40(month){const [y,m]=String(month).split('-').map(Number);return localDateISO(new Date(y,m,0,12));}
function mondayOfDateV40(iso){return startOfWeek(iso);}
function weekEndV40(iso){return dateAdd(mondayOfDateV40(iso),5);}
function clientReportStatusRowV40(id){return (state.clientReports||[]).find(row=>row.id===id)||null;}
function setClientReportStatusV40(id,status,note=''){
  state.clientReports=Array.isArray(state.clientReports)?state.clientReports:[];
  let row=clientReportStatusRowV40(id);
  if(!row){row={id,status:'Ready to review',history:[]};state.clientReports.push(row);}
  row.status=status;row.updatedAt=new Date().toISOString();if(status==='Sent')row.sentAt=row.updatedAt;if(note)row.note=note;
  row.history=row.history||[];row.history.push({at:row.updatedAt,status,note});save();
}
function reportVisitsForClientV40(client,start,end){return (state.visits||[]).filter(visit=>visit.clientId===client.id&&dateBetweenV40(visit.date,start,end));}
function reportSchedulesForClientV40(client,start,end){return (state.schedules||[]).filter(job=>job.clientId===client.id&&dateBetweenV40(job.date,start,end));}
function unresolvedReportJobsV40(client,start,end){
  const today=localDateISO();
  return reportSchedulesForClientV40(client,start,end).filter(job=>String(job.date)<today&&!['completed','cancelled','missed','deferred'].includes(job.status||'')&&!((state.visits||[]).some(visit=>visit.scheduledJobId===job.id||(visit.clientId===job.clientId&&visit.date===job.date))));
}
function reportWorkSummaryV40(visits){
  const counts={};visits.forEach(visit=>(visit.workDone||[]).forEach(task=>{counts[task]=(counts[task]||0)+1;}));
  return Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([task,count])=>`${task}${count>1?` (${count})`:''}`).join(', ')||'General garden-service work completed';
}
function reportPeriodLabelV40(type,start,end){
  if(type==='daily')return fmtDate(start);
  if(type==='weekly')return `${fmtShortDate(start)} – ${fmtShortDate(end)}`;
  return monthLabel(String(start).slice(0,7));
}
function clientReportIdV40(type,client,start,end){return `client-report-${type}-${client.id}-${start}-${end}`;}
function buildClientReportV40(type,client,start,end){
  const visits=reportVisitsForClientV40(client,start,end),unresolved=unresolvedReportJobsV40(client,start,end),statusRow=clientReportStatusRowV40(clientReportIdV40(type,client,start,end));
  const recipients=String(client.reporting?.recipients||client.email||'').trim(),cc=String(client.reporting?.cc||'').trim(),extras=visits.filter(visit=>String(visit.extraDescription||'').trim()),partials=visits.filter(visit=>/partial|incomplete|missed|access|unable/i.test(String(visit.outcome||visit.status||visit.notes||'')));
  const issues=[];if(!recipients)issues.push('Missing recipient email');if(unresolved.length)issues.push(`${unresolved.length} unresolved scheduled visit${unresolved.length===1?'':'s'}`);if(partials.length&&client.reporting?.includeIncomplete==='no')issues.push('Incomplete visit needs office review');
  const automaticStatus=issues.length?'Needs attention':'Ready to review';
  return {id:clientReportIdV40(type,client,start,end),type,client,start,end,visits,unresolved,extras,partials,recipients,cc,issues,status:statusRow?.status||automaticStatus,history:statusRow?.history||[],label:reportPeriodLabelV40(type,start,end)};
}
function clientReportsForMonthV40(month){
  const reports=[];
  (state.clients||[]).filter(isCorporateClientV40).forEach(client=>{
    const monthStart=`${month}-01`,monthEnd=endOfMonthV40(month);
    if(clientReportingEnabledV40(client,'daily')){
      const days=[...new Set(reportVisitsForClientV40(client,monthStart,monthEnd).map(visit=>visit.date))].sort();
      days.forEach(day=>reports.push(buildClientReportV40('daily',client,day,day)));
    }
    if(clientReportingEnabledV40(client,'weekly')){
      const weekStarts=[...new Set(reportVisitsForClientV40(client,monthStart,monthEnd).map(visit=>mondayOfDateV40(visit.date)))].sort();
      weekStarts.forEach(start=>reports.push(buildClientReportV40('weekly',client,start,weekEndV40(start))));
    }
    if(clientReportingEnabledV40(client,'monthly')){
      if(reportVisitsForClientV40(client,monthStart,monthEnd).length)reports.push(buildClientReportV40('monthly',client,monthStart,monthEnd));
    }
  });
  return reports.sort((a,b)=>String(b.end).localeCompare(String(a.end))||a.client.name.localeCompare(b.client.name)||a.type.localeCompare(b.type));
}
function actionableReportsV40(month=currentMonth()){return clientReportsForMonthV40(month).filter(report=>!['Sent','Skipped'].includes(report.status));}
function reportStatusClassV40(status){if(status==='Sent')return 'sent';if(status==='Needs attention')return 'review';if(status==='Skipped')return 'neutral';if(status==='Send later')return 'neutral';return 'ready';}
function reportSubjectV40(report){return `${CLIENT_REPORT_TYPES_V40[report.type]} — ${report.client.name} — ${report.label}`;}
function reportPlainTextV40(report){
  const comm=state.business.clientCommunications||defaultClientCommunicationsV40();
  const intro=report.type==='daily'?comm.corporateDailyTemplate:report.type==='weekly'?comm.corporateWeeklyTemplate:comm.corporateMonthlyTemplate;
  const lines=[intro,'',`${CLIENT_REPORT_TYPES_V40[report.type]}`,`Customer: ${report.client.name}`,`Period: ${report.label}`,'',`Completed visits: ${report.visits.length}`];
  report.visits.forEach(visit=>{const team=teamById(visit.teamId)?.name||'No team',site=clientById(visit.clientId)||report.client,work=reportWorkSummaryV40([visit]);lines.push(`- ${fmtDate(visit.date)} · ${site.address||site.name} · ${team} · ${visit.outcome||'Completed'} · ${work}`);});
  if(report.extras.length&&report.client.reporting?.includeExtras!=='no'){lines.push('',`Extras recorded: ${report.extras.length}`);report.extras.forEach(visit=>lines.push(`- ${fmtDate(visit.date)} · ${visit.extraDescription}`));}
  if(report.unresolved.length){lines.push('',`Work needing attention: ${report.unresolved.length}`);report.unresolved.forEach(job=>lines.push(`- ${fmtDate(job.date)} · scheduled visit still needs an outcome`));}
  if(report.client.reporting?.notes){lines.push('',`Reporting notes: ${report.client.reporting.notes}`);}
  lines.push('',String(comm.corporateReportSignature||'').replace('{business_name}',state.business.name||'TuinBooks'));
  return lines.join('\n');
}
function reportHtmlTableV40(report){
  const visitRows=report.visits.map(visit=>{const site=clientById(visit.clientId)||report.client,team=teamById(visit.teamId)?.name||'No team',work=reportWorkSummaryV40([visit]);return `<tr><td>${esc(fmtDate(visit.date))}</td><td>${esc(site.address||site.name||'Site')}</td><td>${esc(team)}</td><td>${esc(visit.outcome||'Completed')}</td><td>${esc(work)}</td></tr>`;}).join('')||'<tr><td colspan="5">No completed work records in this period.</td></tr>';
  const extras=report.extras.length&&report.client.reporting?.includeExtras!=='no'?`<h3>Extras recorded</h3><ul>${report.extras.map(visit=>`<li>${esc(fmtDate(visit.date))} · ${esc(visit.extraDescription)}</li>`).join('')}</ul>`:'';
  const unresolved=report.unresolved.length?`<h3>Needs office attention</h3><ul>${report.unresolved.map(job=>`<li>${esc(fmtDate(job.date))} · scheduled visit still needs an outcome</li>`).join('')}</ul>`:'';
  return `<div class="client-report-preview"><h2>${esc(CLIENT_REPORT_TYPES_V40[report.type])}</h2><p><strong>${esc(report.client.name)}</strong><br>${esc(report.label)}</p><table class="report-preview-table"><thead><tr><th>Date</th><th>Site</th><th>Team</th><th>Outcome</th><th>Work completed</th></tr></thead><tbody>${visitRows}</tbody></table>${extras}${unresolved}<p class="muted-copy">Photos are not included in corporate email reports.</p></div>`;
}
function clientReportCardV40(report){
  const blocked=report.issues.length>0,statusClass=reportStatusClassV40(report.status),siteCount=new Set(report.visits.map(v=>v.clientId)).size||1;
  return `<article class="client-report-card ${statusClass}"><div class="client-report-card-main"><div><span class="eyebrow">${esc(CLIENT_REPORT_TYPES_V40[report.type])}</span><h3>${esc(report.client.name)}</h3><p>${esc(report.label)} · ${report.visits.length} completed visit${report.visits.length===1?'':'s'} · ${siteCount} site${siteCount===1?'':'s'}</p></div><span class="status-badge ${statusClass}">${esc(report.status)}</span></div><div class="client-report-card-meta"><span>To: ${esc(report.recipients||'Missing recipient')}</span>${report.extras.length?`<span>${report.extras.length} extra${report.extras.length===1?'':'s'} recorded</span>`:''}${report.issues.length?`<span class="report-issue">${esc(report.issues.join(' · '))}</span>`:''}</div><div class="client-report-actions"><button class="button secondary compact" onclick="previewClientReportV40('${report.id}')">Review report</button><button class="button compact" ${blocked?'disabled title="Resolve the attention items before sending"':''} onclick="sendClientReportV40('${report.id}')">Send</button><button class="button secondary compact" onclick="markClientReportV40('${report.id}','Send later')">Send later</button><button class="button danger secondary compact" onclick="markClientReportV40('${report.id}','Skipped')">Do not send</button></div></article>`;
}
function findBuiltReportByIdV40(id){
  const month=$('reportMonth')?.value||currentMonth();
  return clientReportsForMonthV40(month).find(report=>report.id===id)||clientReportsForMonthV40(currentMonth()).find(report=>report.id===id)||null;
}
window.previewClientReportV40=function(id){
  const report=findBuiltReportByIdV40(id);if(!report)return toast('Report could not be found.','error');
  $('invoicePreviewTitle').textContent=reportSubjectV40(report);$('invoicePreviewContent').innerHTML=reportHtmlTableV40(report);$('invoicePreviewDialog').showModal();
};
window.sendClientReportV40=function(id){
  if(!requireOutboundAllowedV5960('email'))return;
  const report=findBuiltReportByIdV40(id);if(!report)return toast('Report could not be found.','error');
  if(report.issues.length){toast('Resolve the attention items before sending this report.','error');return;}
  const to=report.recipients,cc=report.cc,subject=reportSubjectV40(report),body=reportPlainTextV40(report);
  setClientReportStatusV40(id,'Sent','Opened email app from TuinBooks');
  window.location.href=`mailto:${encodeURIComponent(to)}${cc?`?cc=${encodeURIComponent(cc)}&`:'?'}subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  renderClientReportsV40();renderBusinessClientReportAlertV40();toast('Report marked sent and opened in your email app.');
};
window.markClientReportV40=function(id,status){setClientReportStatusV40(id,status);renderClientReportsV40();renderBusinessClientReportAlertV40();toast(`Report marked ${status.toLowerCase()}.`);};
function renderClientReportsV40(){
  const queue=$('clientReportQueue'),summary=$('clientReportsQueueSummary');if(!queue||!summary)return;
  const month=$('reportMonth')?.value||currentMonth(),reports=clientReportsForMonthV40(month),actionable=reports.filter(report=>!['Sent','Skipped'].includes(report.status)),attention=actionable.filter(report=>report.status==='Needs attention');
  summary.innerHTML=actionable.length?`<div><strong>${actionable.length} client report${actionable.length===1?'':'s'} ready for office review</strong><span>${attention.length?`${attention.length} need attention before sending.`:'All ready reports can be reviewed and sent.'}</span></div><button type="button" class="button secondary compact" onclick="showView('reports')">Open reports</button>`:`<div><strong>No client reports waiting</strong><span>Reports appear here when corporate customers have completed work records for the selected month.</span></div>`;
  queue.innerHTML=reports.length?reports.map(clientReportCardV40).join(''):'<div class="client-report-empty">No corporate reports are available for this month. Turn reporting on from a corporate client record after work records exist.</div>';
}
function renderBusinessClientReportAlertV40(){
  const host=$('businessClientReportAlert');if(!host)return;const reports=actionableReportsV40(currentMonth()),attention=reports.filter(report=>report.status==='Needs attention');
  host.innerHTML=reports.length?`<div><strong>${reports.length} client report${reports.length===1?'':'s'} ready to review</strong><span>${attention.length?`${attention.length} need attention before sending.`:'Prepared from completed corporate work records. The office decides whether to send.'}</span></div><button type="button" class="button compact" onclick="showView('reports')">Review reports</button>`:`<div><strong>No client reports waiting</strong><span>Corporate reports will appear here after completed work records are available.</span></div>`;
}
function readClientReportingFormV40(){
  return {
    communicationPreference:$('clientCommunicationPreference')?.value||'WhatsApp',completionReport:$('clientCompletionReport')?.value||'yes',
    reporting:{daily:!!$('clientReportDaily')?.checked,weekly:!!$('clientReportWeekly')?.checked,monthly:!!$('clientReportMonthly')?.checked,recipients:$('clientReportRecipients')?.value.trim()||'',cc:$('clientReportCc')?.value.trim()||'',grouping:$('clientReportGrouping')?.value||'combined',includeIncomplete:$('clientReportIncludeIncomplete')?.value||'yes',includeExtras:$('clientReportIncludeExtras')?.value||'yes',notes:$('clientReportNotes')?.value.trim()||''}
  };
}
function writeClientReportingFormV40(client={}){
  const reporting={daily:false,weekly:false,monthly:false,recipients:client.email||'',cc:'',grouping:'combined',includeIncomplete:'yes',includeExtras:'yes',notes:'',...(client.reporting||{})};
  if($('clientCommunicationPreference'))$('clientCommunicationPreference').value=client.communicationPreference||(client.email?'Email':'WhatsApp');
  if($('clientCompletionReport'))$('clientCompletionReport').value=client.completionReport||'yes';
  if($('clientReportDaily'))$('clientReportDaily').checked=!!reporting.daily;
  if($('clientReportWeekly'))$('clientReportWeekly').checked=!!reporting.weekly;
  if($('clientReportMonthly'))$('clientReportMonthly').checked=!!reporting.monthly;
  if($('clientReportRecipients'))$('clientReportRecipients').value=reporting.recipients||client.email||'';
  if($('clientReportCc'))$('clientReportCc').value=reporting.cc||'';
  if($('clientReportGrouping'))$('clientReportGrouping').value=reporting.grouping||'combined';
  if($('clientReportIncludeIncomplete'))$('clientReportIncludeIncomplete').value=reporting.includeIncomplete||'yes';
  if($('clientReportIncludeExtras'))$('clientReportIncludeExtras').value=reporting.includeExtras||'yes';
  if($('clientReportNotes'))$('clientReportNotes').value=reporting.notes||'';
  toggleClientReportingPanelV40();
}
function toggleClientReportingPanelV40(){
  const panel=$('clientReportingPanel'),type=$('clientCustomerType')?.value||'';if(!panel)return;panel.classList.toggle('hidden',!CORPORATE_CUSTOMER_TYPES_V40.includes(type));
}
const editClientBaseV40=window.editClient||editClient;
window.editClient=function(id){editClientBaseV40(id);const client=clientById(id)||{};writeClientReportingFormV40(client);};
editClient=window.editClient;
const clearClientFormBaseV40=clearClientForm;
clearClientForm=function(){clearClientFormBaseV40();writeClientReportingFormV40({communicationPreference:'WhatsApp',completionReport:'yes',reporting:{daily:false,weekly:false,monthly:false,recipients:'',cc:'',grouping:'combined',includeIncomplete:'yes',includeExtras:'yes',notes:''}});};
const saveClientFormBaseV40=saveClientForm;
saveClientForm=function(event){
  const id=$('clientId')?.value||'',before=new Set((state.clients||[]).map(client=>client.id)),reporting=readClientReportingFormV40();
  saveClientFormBaseV40(event);
  const saved=id?clientById(id):(state.clients||[]).find(client=>!before.has(client.id));
  if(saved){saved.communicationPreference=reporting.communicationPreference;saved.completionReport=reporting.completionReport;saved.reporting={...(saved.reporting||{}),...reporting.reporting};save();renderClients();}
};
const renderSettingsBaseV40=renderSettings;
renderSettings=function(){
  renderSettingsBaseV40();const comm={...defaultClientCommunicationsV40(),...(state.business.clientCommunications||{})};
  if($('settingVisitCompleteTemplate'))$('settingVisitCompleteTemplate').value=comm.visitCompleteTemplate||'';
  if($('settingCorporateDailyTemplate'))$('settingCorporateDailyTemplate').value=comm.corporateDailyTemplate||'';
  if($('settingCorporateWeeklyTemplate'))$('settingCorporateWeeklyTemplate').value=comm.corporateWeeklyTemplate||'';
  if($('settingCorporateMonthlyTemplate'))$('settingCorporateMonthlyTemplate').value=comm.corporateMonthlyTemplate||'';
  if($('settingCorporateReportSignature'))$('settingCorporateReportSignature').value=comm.corporateReportSignature||'';
};
const saveSettingsBaseV40=saveSettings;
saveSettings=function(event){
  saveSettingsBaseV40(event);
  state.business.clientCommunications={visitCompleteTemplate:$('settingVisitCompleteTemplate')?.value.trim()||defaultClientCommunicationsV40().visitCompleteTemplate,corporateDailyTemplate:$('settingCorporateDailyTemplate')?.value.trim()||defaultClientCommunicationsV40().corporateDailyTemplate,corporateWeeklyTemplate:$('settingCorporateWeeklyTemplate')?.value.trim()||defaultClientCommunicationsV40().corporateWeeklyTemplate,corporateMonthlyTemplate:$('settingCorporateMonthlyTemplate')?.value.trim()||defaultClientCommunicationsV40().corporateMonthlyTemplate,corporateReportSignature:$('settingCorporateReportSignature')?.value.trim()||defaultClientCommunicationsV40().corporateReportSignature};
  save();toast('Client communication settings saved.');
};
const renderReportsBaseV40=renderReports;
renderReports=function(){renderReportsBaseV40();renderClientReportsV40();};
const renderYearOverviewBaseV40=renderYearOverview;
renderYearOverview=function(){renderYearOverviewBaseV40();renderBusinessClientReportAlertV40();};
const loadBaseV40=load;
load=function(){loadBaseV40();ensureReportingStateV40();state.version=Math.max(Number(state.version)||1,TUINBOOKS_VERSION_V40);save();};

document.addEventListener('DOMContentLoaded',()=>{
  if(document.body.dataset.app!=='desktop')return;
  $('clientCustomerType')?.addEventListener('change',()=>{toggleClientReportingPanelV40();const type=$('clientCustomerType')?.value||'';if(CORPORATE_CUSTOMER_TYPES_V40.includes(type)&&!$('clientReportRecipients')?.value&&$('clientEmail')?.value)$('clientReportRecipients').value=$('clientEmail').value;});
  $('clientEmail')?.addEventListener('input',()=>{const type=$('clientCustomerType')?.value||'';if(CORPORATE_CUSTOMER_TYPES_V40.includes(type)&&!$('clientReportRecipients')?.value)$('clientReportRecipients').value=$('clientEmail').value;});
  $('refreshClientReportsBtn')?.addEventListener('click',()=>{renderClientReportsV40();toast('Client reports refreshed.');});
});

/* ---------- v41 pilot-ready operational cloud sync and corrected onboarding ---------- */
const TUINBOOKS_VERSION_V41=41;
