/* ---------- v48 office-confirmed suburb assignment ---------- */
const TUINBOOKS_VERSION_V48_CONFIRMED_SUBURBS=true;

function suburbKeyV48(value){return normaliseSuburbV41(value).toLocaleLowerCase('en-ZA');}
function titleCaseSuburbV48(value){
  return normaliseSuburbV41(value).split(' ').map(word=>word.length>2?word.charAt(0).toUpperCase()+word.slice(1).toLowerCase():word).join(' ');
}
function knownSuburbsV48(excludeClientId=''){
  const values=[];
  (state.clients||[]).forEach(client=>{if(client.id!==excludeClientId&&client.suburb)values.push(normaliseSuburbV41(client.suburb));});
  (state.clusters||[]).forEach(cluster=>(cluster.suburbs||[]).forEach(suburb=>values.push(normaliseSuburbV41(suburb))));
  const unique=new Map();values.filter(Boolean).forEach(value=>{const key=suburbKeyV48(value);if(!unique.has(key))unique.set(key,value);});
  return [...unique.values()].sort((a,b)=>a.localeCompare(b));
}
function refreshClientSuburbOptionsV48(){
  const list=$('clientSuburbOptions');if(!list)return;
  const currentId=$('clientId')?.value||'';
  list.innerHTML=knownSuburbsV48(currentId).map(suburb=>`<option value="${esc(suburb)}"></option>`).join('');
}
function addressSuburbSuggestionV48(address,excludeClientId=''){
  const text=normaliseSuburbV41(address);if(!text)return '';
  const lowered=text.toLocaleLowerCase('en-ZA');
  const known=knownSuburbsV48(excludeClientId).sort((a,b)=>b.length-a.length);
  const exactKnown=known.find(suburb=>{
    const key=suburbKeyV48(suburb).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    return new RegExp(`(^|[^a-z0-9])${key}([^a-z0-9]|$)`,'i').test(lowered);
  });
  if(exactKnown)return exactKnown;
  const ignored=new Set(['south africa','western cape','eastern cape','northern cape','gauteng','kwazulu-natal','kwazulu natal','free state','limpopo','mpumalanga','north west']);
  const streetWords=/\b(street|st|road|rd|avenue|ave|drive|dr|lane|ln|close|crescent|cres|boulevard|blvd|way|place|pl|court|ct|terrace|highway|route|farm)\b/i;
  const parts=String(address).split(/[,\n]/).map(part=>normaliseSuburbV41(part)).filter(Boolean);
  const candidates=parts.filter(part=>{
    const key=suburbKeyV48(part);
    if(!key||ignored.has(key)||/^\d{4}$/.test(key)||/^south africa\s*\d*$/.test(key))return false;
    if(/\d/.test(part)&&streetWords.test(part))return false;
    if(/^\d/.test(part))return false;
    return true;
  });
  return candidates.length?titleCaseSuburbV48(candidates[0]):'';
}
function clientSuburbSourceV48(){return $('clientSuburb')?.dataset.source||'';}
function setClientSuburbStatusV48(message){if($('clientSuburbStatus'))$('clientSuburbStatus').textContent=message;}
function renderClientSuburbSuggestionV48(){
  const panel=$('clientSuburbSuggestion'),input=$('clientSuburb');if(!panel||!input)return;
  refreshClientSuburbOptionsV48();
  const suggestion=addressSuburbSuggestionV48($('clientAddress')?.value||'',$('clientId')?.value||'');
  panel.dataset.suggestion=suggestion;
  const confirmed=normaliseSuburbV41(input.value);
  const differs=suggestion&&suburbKeyV48(suggestion)!==suburbKeyV48(confirmed);
  panel.classList.toggle('hidden',!differs);
  if($('clientSuburbSuggestionTitle'))$('clientSuburbSuggestionTitle').textContent=`Suggested from address: ${suggestion||''}`;
  if($('clientSuburbSuggestionText'))$('clientSuburbSuggestionText').textContent='Use it only when it matches the location the office recognises.';
  if(confirmed){
    const source=clientSuburbSourceV48();
    setClientSuburbStatusV48(source==='suggested'?'Suggestion accepted and confirmed by the office. TuinBooks will not replace it automatically.':'Office-confirmed suburb. TuinBooks will not replace it automatically.');
  }else setClientSuburbStatusV48(suggestion?'A possible suburb was found in the address. Confirm it below or type the correct suburb.':'Choose an existing suburb or type the suburb the office uses for this site.');
}
function useClientSuburbSuggestionV48(){
  const input=$('clientSuburb'),panel=$('clientSuburbSuggestion');if(!input||!panel?.dataset.suggestion)return;
  input.value=panel.dataset.suggestion;input.dataset.source='suggested';renderClientSuburbSuggestionV48();
  const mapped=explicitClusterForSuburbV41(input.value);if($('clientCluster')&&!$('clientCluster').value&&mapped)$('clientCluster').value='';
}

