/* ---------- v53 pilot reliability tightening ---------- */
const TUINBOOKS_VERSION_V53=53;
const TUINBOOKS_VERSION_V54=54;
const FIELD_OUTBOX_DB_V53='tuinbooks-field-outbox-v53';
const FIELD_OUTBOX_STORE_V53='operations';
const FIELD_OUTBOX_FALLBACK_V53='tuinbooks_field_outbox_fallback_v53';
const FIELD_WORKSPACE_CACHE_V54='tuinbooks_field_workspace_cache_v54';
let fieldOutboxFlushingV53=false;

function outboxDbV53(){
  return new Promise((resolve,reject)=>{
    if(!window.indexedDB)return reject(new Error('Durable device storage is unavailable.'));
    const request=indexedDB.open(FIELD_OUTBOX_DB_V53,1);
    request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(FIELD_OUTBOX_STORE_V53))db.createObjectStore(FIELD_OUTBOX_STORE_V53,{keyPath:'id'});};
    request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('Could not open durable device storage.'));
  });
}
async function outboxTransactionV53(mode,work){
  const db=await outboxDbV53();
  return new Promise((resolve,reject)=>{const tx=db.transaction(FIELD_OUTBOX_STORE_V53,mode),store=tx.objectStore(FIELD_OUTBOX_STORE_V53);let result;try{result=work(store);}catch(error){db.close();reject(error);return;}tx.oncomplete=()=>{db.close();resolve(result?.result);};tx.onerror=()=>{db.close();reject(tx.error||new Error('Device queue operation failed.'));};});
}
function outboxFallbackRowsV53(){try{return JSON.parse(localStorage.getItem(FIELD_OUTBOX_FALLBACK_V53)||'[]');}catch(error){return [];}}
async function outboxPutV53(operation){
  try{await outboxTransactionV53('readwrite',store=>store.put(operation));}
  catch(error){if(operation.photos?.length)throw error;const rows=outboxFallbackRowsV53().filter(row=>row.id!==operation.id);rows.push(operation);if(!writeStoredJsonV28(FIELD_OUTBOX_FALLBACK_V53,rows))throw error;}
  await renderFieldOutboxStateV53();
}
async function outboxDeleteV53(id){
  try{await outboxTransactionV53('readwrite',store=>store.delete(id));}catch(error){}
  writeStoredJsonV28(FIELD_OUTBOX_FALLBACK_V53,outboxFallbackRowsV53().filter(row=>row.id!==id));await renderFieldOutboxStateV53();
}
async function outboxRowsV53(){
  let rows=[];
  try{rows=await outboxTransactionV53('readonly',store=>store.getAll())||[];}catch(error){}
  const fallback=outboxFallbackRowsV53(),map=new Map([...fallback,...rows].map(row=>[row.id,row]));
  return [...map.values()].sort((a,b)=>String(a.createdAt||'').localeCompare(String(b.createdAt||'')));
}
async function renderFieldOutboxStateV53(error=false){
  const el=$('mobileOutboxState');if(!el)return;const rows=await outboxRowsV53(),mine=rows.filter(outboxOperationSameBusinessV54),failed=mine.filter(row=>row.status==='failed').length;
  el.className=`mobile-outbox-state ${error||failed?'error':mine.length?'pending':''}`;
  el.textContent=failed?`${failed} needs attention · ${mine.length} stored on this phone`:error?`${mine.length||1} item${mine.length===1?'':'s'} waiting for connection`:mine.length?`${mine.length} saved on this phone · waiting to sync`:'All field work synced';
}
function outboxOperationSameBusinessV54(row){return !backendV28.businessId||row.businessId===backendV28.businessId;}
function outboxOperationBelongsHereV54(row){
  if(!outboxOperationSameBusinessV54(row))return false;
  if(backendIsAdminV30())return true;
  const teamId=row.record?.teamId||row.teamId||'';
  return !backendV28.businessId||(backendV28.assignedTeamIds||[]).includes(teamId);
}
function deterministicPhotoPathV53(operation,recordId,index){
  const safeId=String(recordId).replace(/[^a-zA-Z0-9._-]/g,'-'),date=String(operation.record?.date||operation.createdAt||localDateISO()).slice(0,10);
  return `${operation.businessId}/${operation.record.teamId}/${operation.type==='opportunity'?'opportunities':'visits'}/${date}/${safeId}-${index+1}.jpg`;
}
async function uploadOutboxPhotosV53(operation,recordId){
  const paths=[];
  for(let index=0;index<(operation.photos||[]).length;index++){
    const path=deterministicPhotoPathV53(operation,recordId,index),{error}=await backendV28.client.storage.from('tuinbooks-media').upload(path,dataUrlBlobV41(operation.photos[index]),{contentType:'image/jpeg',upsert:false});
    if(error&&!/already exists|duplicate|409|resource exists/i.test(String(error.message||error)))throw error;paths.push(path);
  }
  return paths;
}
async function processVisitOutboxV53(operation){
  const record=operation.record,payload={id:record.id,work_date:record.date,team_id:record.teamId,client_id:record.clientId,work_done:record.workDone||[],extra_description:record.extraDescription||'',photo_paths:[],outcome:record.outcome||'Completed',payload:cleanPayloadPhotosV41(record)};
  const request=record.scheduledJobId?backendV28.client.rpc('complete_schedule_job_v54',{p_business_id:operation.businessId,p_schedule_id:record.scheduledJobId,p_work_record:payload}):backendV28.client.rpc('create_unscheduled_work_record_v54',{p_business_id:operation.businessId,p_work_record:payload});
  const {data,error}=await request;if(error)throw error;const recordId=String(data||record.id),duplicate=recordId!==record.id;
  let photoPaths=[];if(!duplicate){if(operation.photos?.length)photoPaths=await uploadOutboxPhotosV53(operation,recordId);const attached=await backendV28.client.rpc('set_work_record_photos_v54',{p_business_id:operation.businessId,p_work_record_id:recordId,p_photo_paths:photoPaths});if(attached.error)throw attached.error;}
  const local=state.visits.find(item=>item.id===record.id);if(duplicate){state.visits=state.visits.filter(item=>item.id!==record.id);}else if(local){local.photoPaths=photoPaths;local.syncStatus='synced';}
  const schedule=state.schedules.find(item=>item.id===record.scheduledJobId);if(schedule)schedule.status=['Completed','Partially completed'].includes(record.outcome)?'completed':record.outcome==='Weather delay'?'deferred':'missed';saveLocalBaseV28();
}
async function processOpportunityOutboxV53(operation){
  const record=operation.record,linkedVisit=state.visits.find(item=>item.id===record.visitId),photoPaths=await uploadOutboxPhotosV53(operation,record.id),payload={id:record.id,client_id:record.clientId,schedule_job_id:record.scheduleId||null,work_record_id:linkedVisit?.id||null,team_id:record.teamId,category:record.category||'Other',note:record.note||'',photo_paths:photoPaths,payload:cleanPayloadPhotosV41(record)};
  const {error}=await backendV28.client.rpc('create_field_opportunity_v54',{p_business_id:operation.businessId,p_opportunity:payload});if(error)throw error;
  const local=state.opportunities.find(item=>item.id===record.id);if(local){local.photoPaths=photoPaths;local.syncStatus='synced';}saveLocalBaseV28();
}
async function processClientOutboxV54(operation){
  const client=operation.record,customer={id:client.id,name:client.name,customer_type:'Private homeowner',contact_name:'',email:'',phone:client.whatsapp||'',billing_address:'',payload:{...client}},site={id:client.siteId||`site-${client.id}`,customer_id:client.id,site_name:client.name,address:client.address||'',suburb:client.suburb||'',cluster_id:null,access_notes:'',pet_notes:client.gardenNotes||'',instructions:'',payload:{...client}};
  const {error}=await backendV28.client.rpc('create_field_client_v54',{p_business_id:operation.businessId,p_customer:customer,p_site:site,p_team_id:client.teamId});if(error)throw error;
  const local=state.clients.find(item=>item.id===client.id);if(local)local.syncStatus='synced';saveLocalBaseV28();
}
function transientOutboxErrorV54(error){return /failed to fetch|network|timeout|offline|gateway|503|502|504/i.test(String(error?.message||error||''));}
async function flushFieldOutboxV53(){
  if(fieldOutboxFlushingV53||backendV28.mode!=='supabase'||!backendV28.client||!backendV28.businessId||!backendV28.user||navigator.onLine===false)return false;
  fieldOutboxFlushingV53=true;let failed=false;
  try{
    const now=Date.now();
    const rows=(await outboxRowsV53()).filter(outboxOperationBelongsHereV54).filter(row=>!row.nextAttemptAt||Date.parse(row.nextAttemptAt)<=now);
    for(const operation of rows){
      try{
        if(operation.type==='visit')await processVisitOutboxV53(operation);
        else if(operation.type==='opportunity')await processOpportunityOutboxV53(operation);
        else if(operation.type==='client')await processClientOutboxV54(operation);
        else continue;
        await outboxDeleteV53(operation.id);
      }catch(error){
        failed=true;operation.status='failed';operation.attempts=Number(operation.attempts||0)+1;operation.lastError=String(error?.message||error||'Sync failed').slice(0,240);operation.lastAttemptAt=new Date().toISOString();
        const transient=transientOutboxErrorV54(error),delay=transient?Math.min(15*60*1000,30000*(2**Math.max(0,operation.attempts-1))):5*60*1000;
        operation.nextAttemptAt=new Date(Date.now()+delay).toISOString();await outboxPutV53(operation);
        if(transient)break;
      }
    }
  }finally{fieldOutboxFlushingV53=false;await renderFieldOutboxStateV53(failed);}
  return !failed;
}

