/* =========================================================
   v58.9.29 — canonical scheduling renderer
   One live render path. Legacy renderers above are inert.
   ========================================================= */
function renderSchedule(){
  if(typeof ensureV55State==='function')ensureV55State();
  if(typeof ensureV56State==='function')ensureV56State();
  if(typeof applyDueAgreementChangesV56==='function')applyDueAgreementChangesV56();
  if(typeof setCurrentOperatingWeekV5604==='function')setCurrentOperatingWeekV5604(false);
  if(typeof populateScheduleFiltersV55==='function')populateScheduleFiltersV55();

  const dates=scheduleWeekDates();
  if(typeof applyScheduleLifecycleRulesV56==='function')applyScheduleLifecycleRulesV56(dates);
  const allJobs=scheduleAllJobs(dates);
  const visibleJobs=scheduleFilteredJobs(dates);
  const board=$('weeklyScheduleBoard');

  renderRollingScheduleOverviewV58929();
  scheduleAttention(dates);

  if(!(state.teams||[]).length){
    if(board)board.innerHTML='<div class="v56-clear-state">Add a team before scheduling work.</div>';
  }else if(board){
    board.innerHTML=scheduleBoard(dates,visibleJobs,allJobs);
  }

  if($('scheduleWeekSummary'))$('scheduleWeekSummary').textContent=`${visibleJobs.length} shown · ${allJobs.length} total`;
  if($('scheduleModeTitle'))$('scheduleModeTitle').textContent='Detailed week';
  if($('scheduleModeHelp'))$('scheduleModeHelp').textContent='Recurring work is maintained automatically across eight weeks. Drag only exceptions, catch-ups and accepted once-off work.';
  if(typeof renderScheduleDetailV55==='function')renderScheduleDetailV55();
  if(typeof renderWeekReviewV12==='function')renderWeekReviewV12(dates,allJobs);
  renderScheduleQueue();
  if(typeof renderBulkScheduleBarV56==='function')renderBulkScheduleBarV56();
  if(typeof renderScheduleAlertsV14==='function')renderScheduleAlertsV14();
  if(typeof updateWorkAttentionV5604==='function')updateWorkAttentionV5604();
}
window.renderSchedule = renderSchedule; // v59.6.91 cross-wrapper scope export


function initialiseScheduleFoundation(){
  if(activeView==='capacity')activeView='schedule';
  const copy=document.querySelector('.schedule-page-heading p');if(copy)copy.textContent='Place the week like a magnetic whiteboard. Client cards fill each team-day, and only genuine overloads are flagged.';
  document.querySelector('.schedule-workspace-toolbar')?.classList.add('hidden');
  document.querySelectorAll('[data-view="capacity"]').forEach(node=>node.remove());
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&scheduleQueueOpen)closeScheduleQueue();});
  if(document.body.dataset.app==='desktop')renderSchedule();
}
