  if(/Admin access required|permission denied|row-level security|RLS/i.test(text))return 'office access was not accepted by the database';
  if(/duplicate key|unique constraint|invoices_one_active_client_month/i.test(text))return 'duplicate operational records need reconciliation';
  if(/Failed to fetch|NetworkError|offline/i.test(text))return 'the database connection could not be reached';
  if(/invalid input syntax|date\/time field value out of range/i.test(text))return 'one saved record contains an invalid date or value';
