    const seen=new Set((winner.lineItems||[]).map(line=>line.sourceKey||line.id||`${line.description}|${line.qty}|${line.unitPrice}`));
    const uniqueLoserLines=(loser.lineItems||[]).filter(line=>{const lineKey=line.sourceKey||line.id||`${line.description}|${line.qty}|${line.unitPrice}`;if(seen.has(lineKey))return false;seen.add(lineKey);return true;});
