  const jobs=(state.schedules||[]).filter(job=>set.has(job.date)&&String(job.status||'').toLowerCase()!=='cancelled');
  const missed=jobs.filter(job=>typeof scheduleJobNeedsOfficeActionV58928==='function'&&scheduleJobNeedsOfficeActionV58928(job)).length;
