function localProformaNumberV5895(quote){
  const year=new Date().getFullYear(),prefix=String(state.business.proformaPrefix||'PRO').trim().toUpperCase().replace(/[^A-Z0-9]+/g,'')||'PRO';
  if(Number(state.business.proformaSequenceYear||year)!==year){state.business.proformaSequenceYear=year;state.business.nextProforma=1;}
  let next=Math.max(1,Number(state.business.nextProforma||1)),number='';
  const used=new Set((state.quotes||[]).map(row=>String(row.paymentRequestV5895?.number||'')));
  do{number=`${prefix}-${year}-${String(next).padStart(4,'0')}`;next+=1;}while(used.has(number));
  quote.paymentRequestV5895.number=number;state.business.nextProforma=next;state.business.proformaSequenceYear=year;return number;
}
