      const temp={documentType:'quote',number:quoteNumberV5609(quote),date:quote.date||$('quoteDate').value,month:String(quote.date||$('quoteDate').value).slice(0,7),sentAt:quote.sentAt||null,lineItems:JSON.parse(JSON.stringify(quote.lineItems||quoteDraftLines)),notes:typeof quoteCombinedNotesV58940==='function'?quoteCombinedNotesV58940($('quoteNotes').value,terms):$('quoteNotes').value};
