  if(route==='full-prepayment')return stock?`Full payment of ${money(total)} is required before the order will be prepared.`:`Full payment of ${money(total)} is required before the work can be scheduled.`;
  const deposit=Math.min(total,quoteDepositAmountV58940(quote,total)),balance=Math.max(0,round2(total-deposit));
  return stock?`A deposit of ${money(deposit)} is required before the order will be prepared. The remaining ${money(balance)} is due on ${handover}.`:`A deposit of ${money(deposit)} is required before the work can be scheduled. The remaining ${money(balance)} is due after completion.`;
