  function statementTransactions(clientId,start,end){
    const all=[];
    (state.invoices||[]).filter(invoice=>invoice.clientId===clientId&&!['Draft','Ready'].includes(invoice.status)).forEach(invoice=>{
      const date=invoiceDate(invoice),credit=isCredit(invoice);
      all.push({date,type:credit?'Credit note':'Invoice',reference:invoice.number||'',description:credit?(invoice.notes||`Credit for ${invoiceById(invoice.creditedInvoiceId)?.number||'invoice'}`):((invoice.lineItems||[]).map(line=>line.description).filter(Boolean).join(', ')||'Invoice'),debit:credit?0:invoiceTotal(invoice),credit:credit?invoiceTotal(invoice):0});
    });
    (state.adminLifecycleV56.payments||[]).filter(payment=>payment.clientId===clientId&&!payment.reversedAt).forEach(payment=>all.push({date:payment.date||String(payment.createdAt||'').slice(0,10),type:'Payment',reference:payment.reference||invoiceById(payment.invoiceId)?.number||'',description:`Payment received · ${payment.method||'Other'}`,debit:0,credit:Number(payment.amount||0)}));
    all.sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.type).localeCompare(String(b.type)));
    const opening=all.filter(row=>row.date<start).reduce((sum,row)=>sum+Number(row.debit||0)-Number(row.credit||0),0);
    return {opening,rows:all.filter(row=>row.date>=start&&row.date<=end)};
  }

