    const openingRow=`<tr><td>${fmtDate(statement.start)}</td><td>Opening balance</td><td>Balance brought forward</td><td></td><td></td><td>${money(statement.opening)}</td></tr>`;
    return `<article class="statement-document-v58952"><header><div><span class="eyebrow">Account statement</span><h2>${esc(state.business.name||'TuinBooks business')}</h2><p>${esc(state.business.address||'')}</p></div><div><strong>${esc(statement.number)}</strong><span>${fmtDate(statement.createdDate)}</span></div></header><section class="statement-party-v58952"><div><small>Statement for</small><strong>${esc(client.name||'Unknown client')}</strong><span>${esc(client.address||client.suburb||'')}</span></div><div><small>Period</small><strong>${fmtDate(statement.start)} – ${fmtDate(statement.end)}</strong><span>${esc(client.email||client.whatsapp||'')}</span></div></section><div class="statement-table-wrap-v58952"><table><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>${openingRow}${rows||'<tr><td colspan="6">No transactions in this period.</td></tr>'}</tbody></table></div><footer><div><small>Closing balance</small><strong>${money(statement.closing)}</strong></div><p>${esc(state.business.banking||'')}</p></footer></article>`;
