      if(isCredit(invoice))return 'Credited';
      const balance=invoiceBalanceSafe(invoice),paid=(state.adminLifecycleV56?.payments||[]).filter(row=>row.invoiceId===invoice.id&&!row.reversedAt).reduce((sum,row)=>sum+Number(row.amount||0),0);
