async function managementAwaitV59338(promise, timeoutMs, message){
  let timer;
  try{
    return await Promise.race([
      Promise.resolve(promise),
      new Promise((_,reject)=>{
        timer=setTimeout(()=>reject(new Error(message)),timeoutMs);
      })
    ]);
  }finally{
    clearTimeout(timer);
  }
}

