async function loadManagementCoreWorkspaceV59338(businessId){
  const client=backendV28.client;

  // Load one small query at a time. Management previously launched five
  // tenant queries in parallel, which can stall indefinitely when the free
  // Supabase project is under resource pressure.
  const business=await managementQueryV59338(
    'Loading the business account…',
    client.from('businesses').select('id,name,phone,email,address,settings,onboarding_complete,core_revision').eq('id',businessId).single()
  );
  const teams=await managementQueryV59338(
    'Loading teams…',
    client.from('teams').select('id,name,leader_name,capacity_hours,buffer_hours,active,payload,created_at').eq('business_id',businessId).order('created_at')
  );
  const clusters=await managementQueryV59338(
    'Loading service areas…',
    client.from('clusters').select('id,name,color,suburbs,active,payload,created_at').eq('business_id',businessId).order('created_at')
  );
  const customers=await managementQueryV59338(
    'Loading clients…',
    client.from('customers').select('id,name,customer_type,contact_name,email,phone,external_accounting_id,status,billing_profile_id,payload,created_at').eq('business_id',businessId).order('created_at')
  );
  const sites=await managementQueryV59338(
    'Loading service sites…',
    client.from('service_sites').select('id,customer_id,address,suburb,cluster_id,access_notes,pet_notes,instructions,active,payload,created_at').eq('business_id',businessId).order('created_at')
  );

  hydrateWorkspaceStateV28(
    business,
    teams||[],
    clusters||[],
    customers||[],
    sites||[]
  );
}

async function openManagementWorkspaceV5936(session){
  if(backendV28.managementLoadPromiseV5936){
    return backendV28.managementLoadPromiseV5936;
  }

  backendV28.managementLoadPromiseV5936=(async()=>{
    setBackendLoadingV28('Verifying the management session…');

    const requested=managementRequestedBusinessV5936();
    const requestedSession=managementRequestedSessionV5938();

    if(!requested){
      throw new Error('The management link is missing the client business ID.');
    }
    if(!requestedSession){
      throw new Error(
        'The management link is missing the exact session ID. Return to Management and open the client again.'
      );
    }

    const result=await managementAwaitV59338(
      backendV28.client.rpc(
        'tuinbooks_management_open_context_v5938',
        {
          p_business_id:requested,
          p_session_id:requestedSession
        }
      ),
      30000,
      'Management session verification timed out. Supabase did not respond within 30 seconds.'
    );

    if(result?.error)throw result.error;

    const ctx=managementContextRowV5936(result?.data);
    if(!ctx?.business_id){
      throw new Error(
        'The selected management session could not be verified. Return to Management and open the client again.'
      );
    }
    if(String(ctx.business_id)!==String(requested)){
      throw new Error(
        'The active management session belongs to a different client account.'
      );
    }
    if(!managementContextCanReadV5936(ctx)){
      throw new Error('The management session has no account access.');
    }

    try{
      if(backendV28.realtimeChannel){
        await backendV28.client.removeChannel(backendV28.realtimeChannel);
      }
    }catch(_){}

    backendV28.realtimeChannel=null;
    backendV28.session=session;
    backendV28.user=session.user;
    backendV28.mode='supabase';
    backendV28.businessId=ctx.business_id;
    backendV28.role=managementContextCanEditV5936(ctx)?'owner':'support';
    backendV28.displayName=
      ctx.support_display_name
      ||session.user.user_metadata?.display_name
      ||session.user.email
      ||'TuinBooks Management';
    backendV28.assignedTeamIds=[];
    backendV28.handlingUserId=session.user.id;
    backendV28.allowOnboarding=managementContextCanEditV5936(ctx);
    backendV28.supportContext=ctx;
    backendV28.authLoadPromise=null;
    backendV28.authLoadUserId='';

    // v59.3.71: Management used to load only the core account rows. Because
    // hydrateWorkspaceStateV28 starts from seedState(), the screen then showed
    // an empty calendar and no logged jobs even when Supabase still contained
    // them. Keep operational saving locked until the real tenant data is loaded.
    clearTimeout(backendV28.operationalSyncTimer);
    backendV28.operationalSyncTimer=null;
    backendV28.operationalPendingSnapshot=null;
    backendV28.operationalQueued=false;
    backendV28.operationalDirty=false;
    backendV28.managementOperationalLoadRequiredV59371=true;
    backendV28.managementOperationalReadyV59371=false;

    await loadManagementCoreWorkspaceV59338(ctx.business_id);

    // v59.3.72: open Management with the authoritative operational rows, but
    // do not block the whole account on quote-acceptance reconciliation or
    // signed photo URL generation. Those two follow-up tasks can be slow and
    // previously left the client account behind a permanent loading screen.
    setBackendLoadingV28('Loading calendar and completed work…');
    const signedPhotoUrlsBeforeV59372=signedPhotoUrlsV41;
    signedPhotoUrlsV41=async()=>new Map();
    try{
      await managementAwaitV59338(
        loadOperationalStateBaseV58941(ctx.business_id),
        35000,
        'The client calendar and completed-work history did not finish loading within 35 seconds. No client data was changed.'
      );
    }finally{
      signedPhotoUrlsV41=signedPhotoUrlsBeforeV59372;
    }

    if(typeof projectOperationalScheduleV59330==='function')projectOperationalScheduleV59330();
    if(typeof applyImportedRouteAreasV59331==='function')applyImportedRouteAreasV59331();
    try{backendV28.lastOperationalJson=operationalSnapshotJsonV41(makeOperationalSnapshotV41());}catch(_){}

    backendV28.managementOperationalReadyV59371=true;
    subscribeOperationalV41();

    // Complete non-critical enrichment only after the account is usable.
    setTimeout(async()=>{
      try{
        const paths=[
          ...(state.visits||[]).flatMap(item=>item.photoPaths||[]),
          ...(state.opportunities||[]).flatMap(item=>item.photoPaths||[])
        ];
        if(paths.length){
          const urlMap=await managementAwaitV59338(
            signedPhotoUrlsV41(paths),
            15000,
            'Photo preview loading timed out.'
          );
          (state.visits||[]).forEach(item=>item.photos=(item.photoPaths||[]).map(path=>urlMap.get(path)).filter(Boolean));
          (state.opportunities||[]).forEach(item=>item.photos=(item.photoPaths||[]).map(path=>urlMap.get(path)).filter(Boolean));
          if(activeView==='work')renderWork();
        }
      }catch(error){console.warn('Management photo previews were deferred',error);}
      try{await managementAwaitV59338(reconcileQuoteAcceptancesV58941(true),15000,'Quote acceptance refresh timed out.');}
      catch(error){console.warn('Management quote acceptance refresh was deferred',error);}
    },250);

    backendV28.businessId=ctx.business_id;
    backendV28.role=managementContextCanEditV5936(ctx)?'owner':'support';
    backendV28.allowOnboarding=managementContextCanEditV5936(ctx);
    backendV28.handlingUserId=session.user.id;
    backendV28.coreDirty=false;
    backendV28.operationalDirty=false;
    backendV28.pendingSnapshot=null;
    backendV28.operationalPendingSnapshot=null;

    activeView='records';
    qsa('.app-view').forEach(view=>view.classList.toggle('active',view.id==='view-records'));
    qsa('.nav-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.view==='records'));
    hideBackendGateV28();
    await new Promise(resolve=>requestAnimationFrame(()=>resolve()));
    refreshAppAfterCloudLoadV28();

    if($('onboardingDialog')?.open)$('onboardingDialog').close();

    setBackendSyncStateV28(
      managementContextCanEditV5936(ctx)
        ?'Management setup access'
        :'Management read-only',
      'saved'
    );

    renderManagementModeV5936(ctx);

    window.__TUINBOOKS_MANAGEMENT_ROUTING_V5936__={
      version:'59.3.38',
      businessId:ctx.business_id,
      businessName:ctx.business_name||state?.business?.name||''
    };

    return ctx;
  })().finally(()=>{
    backendV28.managementLoadPromiseV5936=null;
  });

  return backendV28.managementLoadPromiseV5936;
}

handleAuthenticatedV28=async function(session,force=false){
  if(!managementRoutingRequestedV5936())return handleAuthenticatedBeforeV5936(session,force);
  if(!session?.user)return showBackendAuthV28();
  try{return await openManagementWorkspaceV5936(session);}
  catch(error){showManagementRoutingErrorV5936(error);}
};
