/* ---------- v59.3.11 management focus/session stability ----------
   Supabase may emit TOKEN_REFRESHED when the browser tab regains focus.
   The management route used to treat every auth refresh as a brand-new
   workspace open, showing the full loading gate and reloading Eden again.
   Keep the verified tenant mounted when the same exact manager session is
   already open, and throttle background operational refreshes in management
   mode so ordinary window switching does not hammer the database. */
const TUINBOOKS_MANAGEMENT_STABILITY_V59311='59.3.11-management-focus-stability';

function managementWorkspaceKeyV59311(){
  const params=new URLSearchParams(window.location.search);
  return `${params.get('business')||''}:${params.get('session')||''}`;
}
function managementWorkspaceAlreadyOpenV59311(session){
  if(!managementRoutingRequestedV5936()||!session?.user)return false;
  const requestedBusiness=managementRequestedBusinessV5936();
  const requestedSession=managementRequestedSessionV5938();
  const ctx=backendV28.supportContext;
  return !!(
    requestedBusiness&&requestedSession&&ctx&&
    String(backendV28.businessId||'')===String(requestedBusiness)&&
    String(ctx.business_id||'')===String(requestedBusiness)&&
    String(ctx.session_id||'')===String(requestedSession)&&
    String(backendV28.managementWorkspaceKeyV59311||'')===managementWorkspaceKeyV59311()&&
    backendV28.managementOperationalReadyV59371===true&&
    String(backendV28.handlingUserId||session.user.id)===String(session.user.id)
  );
}

const openManagementWorkspaceBaseV59311=openManagementWorkspaceV5936;
openManagementWorkspaceV5936=async function openManagementWorkspaceV59311(session){
  if(managementWorkspaceAlreadyOpenV59311(session)){
    // Token/session refresh only: update the auth object without remounting the
    // client workspace, changing view, clearing forms, or showing a loading gate.
    backendV28.session=session;
    backendV28.user=session.user;
    backendV28.mode='supabase';
    backendV28.handlingUserId=session.user.id;
    backendV28.authLoadPromise=null;
    backendV28.authLoadUserId='';
    if(document.body.classList.contains('backend-locked'))hideBackendGateV28();
    renderManagementModeV5936(backendV28.supportContext);
    return backendV28.supportContext;
  }
  const result=await openManagementWorkspaceBaseV59311(session);
  const ctx=backendV28.supportContext;
  if(ctx&&String(ctx.business_id||'')===String(managementRequestedBusinessV5936())&&
      String(ctx.session_id||'')===String(managementRequestedSessionV5938())){
    backendV28.managementWorkspaceKeyV59311=managementWorkspaceKeyV59311();
  }
  return result;
};

const scheduleOperationalReloadBaseV59311=scheduleOperationalReloadV41;
scheduleOperationalReloadV41=function scheduleOperationalReloadV59311(){
  if(managementRoutingRequestedV5936()){
    const now=Date.now();
    if(now-Number(backendV28.lastManagementFocusReloadV59311||0)<15000)return;
    backendV28.lastManagementFocusReloadV59311=now;
  }
  return scheduleOperationalReloadBaseV59311();
};

window.__tuinbooksManagementStability=TUINBOOKS_MANAGEMENT_STABILITY_V59311;


/* ---------- v59.3.14 mobile route auto-refresh ----------
   Field phones must receive office schedule changes without a full page reload.
   Use a lightweight, mobile-only poll of today's assigned route as a fallback
   alongside Supabase Realtime. Refresh while the route screen is visible,
   immediately when the phone returns to the app or reconnects, and never while
   a visit form or unsynced field submission is in progress. */
const TUINBOOKS_MOBILE_AUTO_REFRESH_V59314='59.3.14-mobile-route-auto-refresh';
const MOBILE_ROUTE_REFRESH_MS_V59314=60000;
backendV28.mobileRouteRefreshTimerV59314=null;
backendV28.mobileRouteRefreshBusyV59314=false;
backendV28.mobileRouteLastRefreshV59314=0;
backendV28.mobileRouteFailureCountV59460=0;
backendV28.mobileRouteBackoffUntilV59460=0;

