  if(navigator.onLine===false||document.visibilityState!=='visible')return false;
  if(backendV28.mobileRouteRefreshBusyV59314||backendV28.operationalSyncing||fieldOutboxFlushingV53)return false;
  if(document.querySelector('dialog[open]'))return false;
  if(activeMobileClientId)return false;
