    if(!rows.some(isDiaryScheduleJobV59323))protectedGroups.delete(key);
    else protectedGroups.set(key,[...rows].sort((a,b)=>(Number(a.sort)||9999)-(Number(b.sort)||9999)).map(job=>job.id));
