async function ensureCommercialQuoteOnlineV5954(quote){
  if(!quote?.id)throw new Error('The quote could not be found in this workspace.');
  if(backendV28.mode!=='supabase'||!backendV28.client||!backendV28.businessId)return true;
  if(!await commercialPersistV59400({operational:true}))throw new Error('The quote could not be saved online. Nothing was sent.');
  const lookup=async()=>backendV28.client.from('quotes').select('id').eq('business_id',backendV28.businessId).eq('id',quote.id).maybeSingle();
  let result=await lookup();
  if(result.error)throw new Error(backendErrorMessageV28(result.error));
  if(result.data?.id)return true;

  // Recovery for a tab that was already open on v59.5.0–v59.5.3: its first
  // operational save may already have been swallowed by the missing baseline.
  // Send this one quote through the existing delta RPC, then verify it exists.
  const quoteRow=makeOperationalSnapshotV41().p_quotes.find(row=>String(row.id)===String(quote.id));
  if(!quoteRow)throw new Error('The quote could not be prepared for online saving.');
  const payload={
    p_business_id:backendV28.businessId,
    p_expected_revision:Number(backendV28.operationalRevision||0),
    p_schedules:[],p_work_records:[],p_opportunities:[],p_quotes:[quoteRow],p_invoices:[],p_meta:null,
    p_deleted_schedule_ids:[],p_deleted_quote_ids:[],p_deleted_invoice_ids:[]
  };
  const saved=await backendV28.client.rpc('tuinbooks_save_operational_delta_v59394',payload);
  if(saved.error)throw new Error(operationalDeltaErrorV59394(saved.error));
  backendV28.operationalRevision=Number(saved.data?.revision??backendV28.operationalRevision+1);
  backendV28.lastOperationalJson=operationalSnapshotJsonV41(makeOperationalSnapshotV41());
  result=await lookup();
  if(result.error)throw new Error(backendErrorMessageV28(result.error));
  if(!result.data?.id)throw new Error('The quote was not confirmed online, so nothing was sent. Reload Quotes and try once more.');
  return true;
}
