  const combined=`${arrangement} ${basis}`;
  if(/per visit|per service|per delivery|per week/.test(combined))return positiveMoneyV59376(client.rateAmount,client.perVisitRate,client.visitRate)>0?'per_visit':'hold';
  if(/monthly fixed|fixed fee|recurring package|listed amount/.test(combined)||Number(client.monthlyFee||0)>0)return positiveMoneyV59376(client.monthlyFee,client.rateAmount)>0?'monthly_fixed':'hold';
  if(/quote/.test(combined))return 'quote';
