/* ==========================================================================
   TuinBooks v59.6.92 — restore today's Work progress by team
   --------------------------------------------------------------------------
   Narrow UI-only patch on top of v59.6.91.
   It does not alter auth, Management support routing, workspace loading,
   schedule records, work-record persistence, billing, or navigation.
   ========================================================================== */
const TUINBOOKS_WORK_TEAM_PROGRESS_V59692='59.6.92-work-team-progress-restored';

function localTodayV59692(){
  const now=new Date();
  const y=now.getFullYear();
  const m=String(now.getMonth()+1).padStart(2,'0');
  const d=String(now.getDate()).padStart(2,'0');
  return `${y}-${m}-${d}`;
}

function finalWorkTeamRowsV59692(){
  const today=localTodayV59692();
  const teams=(window.state?.teams||[]).filter(team=>team&&team.active!==false);
  const visits=window.state?.visits||[];
  const schedules=window.state?.schedules||[];
  const visitBySchedule=new Set(
    visits
      .filter(visit=>String(visit?.date||'').slice(0,10)===today)
      .map(visit=>String(visit?.scheduledJobId||''))
      .filter(Boolean)
  );

  return teams.map(team=>{
    const jobs=schedules.filter(job=>{
      if(String(job?.date||'').slice(0,10)!==today)return false;
      if(String(job?.teamId||'')!==String(team.id||''))return false;
      const status=String(job?.status||'').toLowerCase();
      return !['cancelled','canceled','rescheduled','deferred'].includes(status);
    });
    const completed=jobs.filter(job=>
      String(job?.status||'').toLowerCase()==='completed' ||
      visitBySchedule.has(String(job?.id||''))
    ).length;
    const total=jobs.length;
    const remaining=Math.max(0,total-completed);
    const pct=total?Math.max(0,Math.min(100,Math.round(completed/total*100))):0;
    return {team,total,completed,remaining,pct};
  }).filter(row=>row.total>0);
}

function workTeamProgressHtmlV59692(){
  const rows=finalWorkTeamRowsV59692();
  if(!rows.length)return '';
  return `<section class="work-team-progress-v59692" aria-label="Today's team progress">
    <div class="work-team-progress-head-v59692">
      <div>
        <span class="eyebrow">Today by team</span>
        <strong>Route completion</strong>
      </div>
      <small>Completed scheduled visits / today’s scheduled route</small>
    </div>
    <div class="work-team-progress-grid-v59692">
      ${rows.map(({team,total,completed,remaining,pct})=>`
        <article class="work-team-meter-v59692 ${pct===100?'complete':''}">
          <div class="work-team-meter-top-v59692">
            <div>
              <strong>${window.esc(String(team.name||'Team'))}</strong>
              <span>${completed} of ${total} completed</span>
            </div>
            <b>${pct}%</b>
          </div>
          <div class="work-team-meter-track-v59692" role="progressbar" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${completed}" aria-label="${window.esc(String(team.name||'Team'))}: ${completed} of ${total} completed">
            <i style="width:${pct}%"></i>
          </div>
          <small>${remaining?`${remaining} remaining`:'Route complete'}</small>
        </article>
      `).join('')}
    </div>
  </section>`;
}

