window.__tuinbooksOnboardingAccessBuildV59693='59.6.93-onboarding-access-hardening';
window.__tuinbooksBuild='59.6.93-onboarding-access-hardening';


/* v59.6.96 — Work today/past-team status repair marker */
const TUINBOOKS_WORK_STATUS_TEAM_REPAIR_V59696='59.6.96-work-status-team-groups';
