/* ========================================================================== 
   TuinBooks v60.0.1 CANARY — Schedule consolidation Stage 1A
   --------------------------------------------------------------------------
   Scope of this stage ONLY:
   - one authoritative Schedule renderer at the end of the v60 canary bundle;
   - previous 4 weeks + current/future 8-week strip;
   - Previous week / Today / Next week navigation;
   - historical weeks are view-only through the existing past-date board rules;
   - compact rolling-week presentation;
   - NO Schedule/Work consistency repair and NO save() from this renderer.

   Later Stage 1 sub-phases will consolidate missed-work resolution,
   day instructions/ad-hoc events, and the scheduling queue into this same path.
   ========================================================================== */
const TUINBOOKS_CONSOLIDATION_SCHEDULE_V6001='60.0.1-schedule-history-compact';

function scheduleCurrentWeekV6001(){return startOfWeek(localDateISO());}
function scheduleMinWeekV6001(){return dateAdd(scheduleCurrentWeekV6001(),-28);}
function scheduleMaxWeekV6001(){return dateAdd(scheduleCurrentWeekV6001(),49);}
function scheduleClampWeekV6001(value){
  const target=startOfWeek(value||localDateISO()),min=scheduleMinWeekV6001(),max=scheduleMaxWeekV6001();
  return target<min?min:target>max?max:target;
}
function scheduleSetWeekV6001(value){
  const picker=$('scheduleWeekPicker');if(!picker)return;
  picker.value=scheduleClampWeekV6001(value);renderSchedule();
}
window.shiftScheduleWeekV6001=function(delta){scheduleSetWeekV6001(dateAdd(scheduleClampWeekV6001($('scheduleWeekPicker')?.value||localDateISO()),Number(delta||0)*7));};
window.goToCurrentScheduleWeekV6001=function(){scheduleSetWeekV6001(scheduleCurrentWeekV6001());};
window.openScheduleWeekV6001=function(weekStart){scheduleSetWeekV6001(weekStart);};

function scheduleWeekSummaryV6001(weekStart){
  const dates=weekDates(weekStart),set=new Set(dates),today=localDateISO();
  const jobs=(state.schedules||[]).filter(job=>set.has(String(job.date||'').slice(0,10))&&String(job.status||'').toLowerCase()!=='cancelled');
  const completed=jobs.filter(job=>String(job.status||'').toLowerCase()==='completed').length;
  const unresolved=jobs.filter(job=>{
    const date=String(job.date||'').slice(0,10),status=String(job.status||'').toLowerCase();
    if(date>=today)return false;
    if(['completed','cancelled','canceled','deferred','rescheduled','no-charge','access-failed'].includes(status))return false;
    try{return typeof scheduleJobNeedsOfficeActionV58928==='function'?!!scheduleJobNeedsOfficeActionV58928(job):true;}catch(error){return true;}
  }).length;
  const hours=jobs.reduce((sum,job)=>sum+Number(job.estimatedHours||0),0);
  const queue=(state.scheduleOverflowQueue||[]).filter(item=>item.weekStart===weekStart).length;
  return {weekStart,jobs:jobs.length,completed,unresolved,hours,queue,historical:weekStart<scheduleCurrentWeekV6001()};
}
function scheduleRollingWeeksV6001(){
  const current=scheduleCurrentWeekV6001(),starts=[];
  for(let days=-28;days<=49;days+=7)starts.push(dateAdd(current,days));
  return starts.map(scheduleWeekSummaryV6001);
}
function renderRollingScheduleOverviewV6001(){
  const host=$('rollingScheduleOverview'),picker=$('scheduleWeekPicker');if(!host||!picker)return;
  const selected=scheduleClampWeekV6001(picker.value||scheduleCurrentWeekV6001());
  picker.min=scheduleMinWeekV6001();picker.max=scheduleMaxWeekV6001();if(picker.value!==selected)picker.value=selected;
  const weeks=scheduleRollingWeeksV6001(),isHistory=selected<scheduleCurrentWeekV6001();
  host.innerHTML=`<div class="rolling-plan-head v6001-rolling-head"><div><span class="eyebrow">Schedule</span><strong>Previous month + 8-week plan</strong><small>Past weeks are history only. Current and future weeks remain operational.</small></div><span class="rolling-plan-status">${isHistory?'Viewing history':'Live schedule'}</span></div>
    <div class="schedule-history-nav-v6001">
      <button type="button" class="button secondary compact" ${selected<=scheduleMinWeekV6001()?'disabled':''} onclick="shiftScheduleWeekV6001(-1)">‹ Previous week</button>
      <button type="button" class="button secondary compact" onclick="goToCurrentScheduleWeekV6001()">Today</button>
      <button type="button" class="button secondary compact" ${selected>=scheduleMaxWeekV6001()?'disabled':''} onclick="shiftScheduleWeekV6001(1)">Next week ›</button>
      <span>${fmtShortDate(selected)}–${fmtShortDate(dateAdd(selected,5))}${isHistory?' · history':''}</span>
    </div>
    <div class="rolling-week-strip v6001-week-strip">${weeks.map(row=>`<button type="button" class="rolling-week-card v6001-week-card ${row.weekStart===selected?'active':''} ${row.unresolved?'attention':''} ${row.historical?'history':''}" onclick="openScheduleWeekV6001('${row.weekStart}')" title="${row.historical?'Historical week — view only':'Schedule week'}"><span>${fmtShortDate(row.weekStart)}</span><strong>${row.jobs}</strong><small>${row.historical?`${row.completed} done${row.unresolved?` · ${row.unresolved} unresolved`:''}`:`${row.hours.toFixed(1)}h${row.queue?` · ${row.queue} unplaced`:''}`}</small></button>`).join('')}</div>`;
}

function renderScheduleConsolidatedV6001(){
  const picker=$('scheduleWeekPicker');
  if(picker){const clamped=scheduleClampWeekV6001(picker.value||scheduleCurrentWeekV6001());if(picker.value!==clamped)picker.value=clamped;}
  const dates=weekDates(picker?.value||scheduleCurrentWeekV6001());
  const allJobs=scheduleAllJobs(dates),visibleJobs=scheduleFilteredJobs(dates),board=$('weeklyScheduleBoard');

  // Pure rendering only. No repair/migration/save side effects are allowed in this renderer.
  if(typeof populateScheduleFiltersV55==='function')populateScheduleFiltersV55();
  renderRollingScheduleOverviewV6001();
  scheduleAttention(dates);

  if(!(state.teams||[]).length){
    if(board)board.innerHTML='<div class="v56-clear-state">Add a team before scheduling work.</div>';
  }else if(board){
    board.innerHTML=scheduleBoard(dates,visibleJobs,allJobs);
  }

  const historical=(picker?.value||scheduleCurrentWeekV6001())<scheduleCurrentWeekV6001();
  if($('scheduleWeekSummary'))$('scheduleWeekSummary').textContent=`${visibleJobs.length} shown · ${allJobs.length} total${historical?' · history':''}`;
  if($('scheduleModeTitle'))$('scheduleModeTitle').textContent=historical?'Historical week':'Detailed week';
  if($('scheduleModeHelp'))$('scheduleModeHelp').textContent=historical?'Past weeks are view-only. Resolve missed work through the explicit outcome controls; history is not regenerated.':'Drag only genuine exceptions, catch-ups and accepted once-off work. Recurring work remains on its confirmed pattern.';

  if(typeof renderScheduleDetailV55==='function')renderScheduleDetailV55();
  if(typeof renderWeekReviewV12==='function')renderWeekReviewV12(dates,allJobs);
  if(typeof renderScheduleQueue==='function')renderScheduleQueue();
  if(typeof renderScheduleAlertsV14==='function')renderScheduleAlertsV14();
  if(typeof updateWorkAttentionV5604==='function')updateWorkAttentionV5604();

  document.body?.classList.toggle('v6001-schedule-history',historical);
  document.documentElement.dataset.scheduleRenderer='v6001';
  window.__tuinbooksScheduleConsolidationV6001={
    build:TUINBOOKS_CONSOLIDATION_SCHEDULE_V6001,
    selectedWeek:picker?.value||'',historical,renderedAt:new Date().toISOString()
  };
}

// This is deliberately the LAST Schedule assignment inside the canary bundle.
// All legacy Schedule renderers above remain present for reference during consolidation,
// but no longer own the live canary render path.
renderSchedule=renderScheduleConsolidatedV6001;
window.renderSchedule=renderScheduleConsolidatedV6001;
window.renderRollingScheduleOverviewV6001=renderRollingScheduleOverviewV6001;
window.__tuinbooksConsolidatedScheduleBuild=TUINBOOKS_CONSOLIDATION_SCHEDULE_V6001;

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>{if(document.body?.dataset?.app==='desktop'&&activeView==='schedule')renderScheduleConsolidatedV6001();},0));
}else{
  setTimeout(()=>{if(document.body?.dataset?.app==='desktop'&&activeView==='schedule')renderScheduleConsolidatedV6001();},0);
}
